/**
 * Test recover lease eventually succeeding.
 */
@Test
public void testRecoverLease() throws IOException {
    long startTime = EnvironmentEdgeManager.currentTime();
    HTU.getConfiguration().setInt("hbase.lease.recovery.dfs.timeout", 1000);
    CancelableProgressable reporter = Mockito.mock(CancelableProgressable.class);
    Mockito.when(reporter.progress()).thenReturn(true);
    DistributedFileSystem dfs = Mockito.mock(DistributedFileSystem.class);
    // Fail four times and pass on the fifth.
    Mockito.when(dfs.recoverLease(FILE)).thenReturn(false).thenReturn(false).thenReturn(false).thenReturn(false).thenReturn(true);
    RecoverLeaseFSUtils.recoverFileLease(dfs, FILE, HTU.getConfiguration(), reporter);
    Mockito.verify(dfs, Mockito.times(5)).recoverLease(FILE);
    // Make sure we waited at least hbase.lease.recovery.dfs.timeout * 3 (the first two
    // invocations will happen pretty fast... the we fall into the longer wait loop).
    assertTrue((EnvironmentEdgeManager.currentTime() - startTime) > (3 * HTU.getConfiguration().getInt("hbase.lease.recovery.dfs.timeout", 61000)));
}

/**
 * Test that isFileClosed makes us recover lease faster.
 */
@Test
public void testIsFileClosed() throws IOException {
    // Make this time long so it is plain we broke out because of the isFileClosed invocation.
    HTU.getConfiguration().setInt("hbase.lease.recovery.dfs.timeout", 100000);
    CancelableProgressable reporter = Mockito.mock(CancelableProgressable.class);
    Mockito.when(reporter.progress()).thenReturn(true);
    IsFileClosedDistributedFileSystem dfs = Mockito.mock(IsFileClosedDistributedFileSystem.class);
    // Now make it so we fail the first two times -- the two fast invocations, then we fall into
    // the long loop during which we will call isFileClosed.... the next invocation should
    // therefore return true if we are to break the loop.
    Mockito.when(dfs.recoverLease(FILE)).thenReturn(false).thenReturn(false).thenReturn(true);
    Mockito.when(dfs.isFileClosed(FILE)).thenReturn(true);
    RecoverLeaseFSUtils.recoverFileLease(dfs, FILE, HTU.getConfiguration(), reporter);
    Mockito.verify(dfs, Mockito.times(2)).recoverLease(FILE);
    Mockito.verify(dfs, Mockito.times(1)).isFileClosed(FILE);
}

// implements all test cases in 1 test since incremental full backup/
// incremental backup has dependencies
@Test
public void testBackupLogCleaner() throws Exception {
    // #1 - create full backup for all tables
    LOG.info("create full backup image for all tables");
    List<TableName> tableSetFullList = Lists.newArrayList(table1, table2, table3, table4);
    try (BackupSystemTable systemTable = new BackupSystemTable(TEST_UTIL.getConnection())) {
        // Verify that we have no backup sessions yet
        assertFalse(systemTable.hasBackupSessions());
        List<FileStatus> walFiles = getListOfWALFiles(TEST_UTIL.getConfiguration());
        BackupLogCleaner cleaner = new BackupLogCleaner();
        cleaner.setConf(TEST_UTIL.getConfiguration());
        Map<String, Object> params = new HashMap<>();
        params.put(HMaster.MASTER, TEST_UTIL.getHBaseCluster().getMaster());
        cleaner.init(params);
        cleaner.setConf(TEST_UTIL.getConfiguration());
        Iterable<FileStatus> deletable = cleaner.getDeletableFiles(walFiles);
        int size = Iterables.size(deletable);
        // We can delete all files because we do not have yet recorded backup sessions
        assertTrue(size == walFiles.size());
        String backupIdFull = fullTableBackup(tableSetFullList);
        assertTrue(checkSucceeded(backupIdFull));
        // Check one more time
        deletable = cleaner.getDeletableFiles(walFiles);
        // We can delete wal files because they were saved into backup system table table
        size = Iterables.size(deletable);
        assertTrue(size == walFiles.size());
        List<FileStatus> newWalFiles = getListOfWALFiles(TEST_UTIL.getConfiguration());
        LOG.debug("WAL list after full backup");
        // New list of wal files is greater than the previous one,
        // because new wal per RS have been opened after full backup
        assertTrue(walFiles.size() < newWalFiles.size());
        Connection conn = ConnectionFactory.createConnection(conf1);
        // #2 - insert some data to table
        Table t1 = conn.getTable(table1);
        Put p1;
        for (int i = 0; i < NB_ROWS_IN_BATCH; i++) {
            p1 = new Put(Bytes.toBytes("row-t1" + i));
            p1.addColumn(famName, qualName, Bytes.toBytes("val" + i));
            t1.put(p1);
        }
        t1.close();
        Table t2 = conn.getTable(table2);
        Put p2;
        for (int i = 0; i < 5; i++) {
            p2 = new Put(Bytes.toBytes("row-t2" + i));
            p2.addColumn(famName, qualName, Bytes.toBytes("val" + i));
            t2.put(p2);
        }
        t2.close();
        // #3 - incremental backup for multiple tables
        List<TableName> tableSetIncList = Lists.newArrayList(table1, table2, table3);
        String backupIdIncMultiple = backupTables(BackupType.INCREMENTAL, tableSetIncList, BACKUP_ROOT_DIR);
        assertTrue(checkSucceeded(backupIdIncMultiple));
        deletable = cleaner.getDeletableFiles(newWalFiles);
        assertTrue(Iterables.size(deletable) == newWalFiles.size());
        conn.close();
    }
}

