@Test
public void testFilesystemWalHostNameParsing() throws IOException {
    String[] hosts = new String[] { "10.20.30.40", "127.0.0.1", "localhost", "a-region-server.domain.com" };
    Path walRootDir = CommonFSUtils.getWALRootDir(conf);
    Path oldLogDir = new Path(walRootDir, HConstants.HREGION_OLDLOGDIR_NAME);
    int port = 60030;
    for (String host : hosts) {
        ServerName serverName = ServerName.valueOf(host, port, 1234);
        Path testOldWalPath = new Path(oldLogDir, serverName + BackupUtils.LOGNAME_SEPARATOR + EnvironmentEdgeManager.currentTime());
        Assert.assertEquals(host + Addressing.HOSTNAME_PORT_SEPARATOR + port, BackupUtils.parseHostFromOldLog(testOldWalPath));
        Path testMasterWalPath = new Path(oldLogDir, testOldWalPath.getName() + MasterRegionFactory.ARCHIVED_WAL_SUFFIX);
        Assert.assertNull(BackupUtils.parseHostFromOldLog(testMasterWalPath));
        // org.apache.hadoop.hbase.wal.BoundedGroupingStrategy does this
        Path testOldWalWithRegionGroupingPath = new Path(oldLogDir, serverName + BackupUtils.LOGNAME_SEPARATOR + serverName + BackupUtils.LOGNAME_SEPARATOR + "regiongroup-0" + BackupUtils.LOGNAME_SEPARATOR + EnvironmentEdgeManager.currentTime());
        Assert.assertEquals(host + Addressing.HOSTNAME_PORT_SEPARATOR + port, BackupUtils.parseHostFromOldLog(testOldWalWithRegionGroupingPath));
    }
}

