    for (Map.Entry<RegionInfo, ServerName[]> entry : secondaryAndTertiaryMap.entrySet()) {
        ServerName[] allServersForRegion = entry.getValue();
        String primaryRSRack = rackManager.getRack(primaryRSMap.get(entry.getKey()));
