public void itSupportsOtherExceptionNanos() {
    HBaseServerExceptionPauseManager pauseManager = new HBaseServerExceptionPauseManager(PAUSE_NANOS, PAUSE_NANOS_FOR_SERVER_OVERLOADED, 0);
    OptionalLong pauseNanos = pauseManager.getPauseNsFromException(OTHER_EXCEPTION, 1, System.nanoTime());
    assertTrue(pauseNanos.isPresent());
