@Test
public void testMetricsWithMultiConnections() throws IOException {
    Configuration conf = new Configuration();
    conf.setBoolean(MetricsConnection.CLIENT_SIDE_METRICS_ENABLED_KEY, true);
    conf.set(MetricsConnection.METRICS_SCOPE_KEY, "unit-test");
    User user = User.getCurrent();
    /* create multiple connections */
    final int num = 3;
    AsyncConnectionImpl impl;
    List<AsyncConnectionImpl> connList = new ArrayList<AsyncConnectionImpl>();
    for (int i = 0; i < num; i++) {
        impl = new AsyncConnectionImpl(conf, null, null, null, user);
        connList.add(impl);
    }
    /* verify metrics presence */
    impl = connList.get(0);
    Optional<MetricsConnection> metrics = impl.getConnectionMetrics();
    assertTrue("Metrics should be present", metrics.isPresent());
    /* verify connection count in a shared metrics */
    long count = metrics.get().getConnectionCount();
    assertEquals("Failed to verify connection count." + count, count, num);
    /* close some connections */
    for (int i = 0; i < num - 1; i++) {
        connList.get(i).close();
    }
    /* verify metrics presence again */
    impl = connList.get(num - 1);
    metrics = impl.getConnectionMetrics();
    assertTrue("Metrics should be present after some of connections are closed.", metrics.isPresent());
    /* verify count of remaining connections */
    count = metrics.get().getConnectionCount();
    assertEquals("Connection count suppose to be 1 but got: " + count, count, 1);
    /* shutdown */
    impl.close();
}

@Test
public void testStaticMetrics() throws IOException {
    final byte[] foo = Bytes.toBytes("foo");
    String table = "TableX";
    final RegionSpecifier region = RegionSpecifier.newBuilder().setValue(ByteString.copyFromUtf8(table)).setType(RegionSpecifierType.REGION_NAME).build();
    final int loop = 5;
    for (int i = 0; i < loop; i++) {
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Get"), TableName.valueOf(table), GetRequest.newBuilder().setRegion(region).setGet(ProtobufUtil.toGet(new Get(foo))).build(), MetricsConnection.newCallStats(), null);
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Scan"), TableName.valueOf(table), ScanRequest.newBuilder().setRegion(region).setScan(ProtobufUtil.toScan(new Scan(new Get(foo)))).build(), MetricsConnection.newCallStats(), new RemoteWithExtrasException("java.io.IOException", null, false, false));
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Multi"), TableName.valueOf(table), MultiRequest.newBuilder().addRegionAction(ClientProtos.RegionAction.newBuilder().addAction(ClientProtos.Action.newBuilder().setGet(ProtobufUtil.toGet(new Get(foo))).build()).setRegion(region).build()).build(), MetricsConnection.newCallStats(), new CallTimeoutException("test with CallTimeoutException"));
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Mutate"), TableName.valueOf(table), MutateRequest.newBuilder().setMutation(ProtobufUtil.toMutation(MutationType.APPEND, new Append(foo))).setRegion(region).build(), MetricsConnection.newCallStats(), null);
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Mutate"), TableName.valueOf(table), MutateRequest.newBuilder().setMutation(ProtobufUtil.toMutation(MutationType.DELETE, new Delete(foo))).setRegion(region).build(), MetricsConnection.newCallStats(), null);
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Mutate"), TableName.valueOf(table), MutateRequest.newBuilder().setMutation(ProtobufUtil.toMutation(MutationType.INCREMENT, new Increment(foo))).setRegion(region).build(), MetricsConnection.newCallStats(), null);
        METRICS.updateRpc(ClientService.getDescriptor().findMethodByName("Mutate"), TableName.valueOf(table), MutateRequest.newBuilder().setMutation(ProtobufUtil.toMutation(MutationType.PUT, new Put(foo))).setRegion(region).build(), MetricsConnection.newCallStats(), new CallTimeoutException("test with CallTimeoutException"));
    }
    testRpcCallMetrics(table, loop);
    String metricKey;
    long metricVal;
    Counter counter;
    // remote exception
    metricKey = "rpcRemoteExceptions_IOException";
    counter = METRICS.getRpcCounters().get(metricKey);
    metricVal = (counter != null) ? counter.getCount() : 0;
    assertEquals("metric: " + metricKey + " val: " + metricVal, metricVal, loop);
    // local exception
    metricKey = "rpcLocalExceptions_CallTimeoutException";
    counter = METRICS.getRpcCounters().get(metricKey);
    metricVal = (counter != null) ? counter.getCount() : 0;
    assertEquals("metric: " + metricKey + " val: " + metricVal, metricVal, loop * 2);
    // total exception
    metricKey = "rpcTotalExceptions";
    counter = METRICS.getRpcCounters().get(metricKey);
    metricVal = (counter != null) ? counter.getCount() : 0;
    assertEquals("metric: " + metricKey + " val: " + metricVal, metricVal, loop * 3);
    testRpcCallTableMetrics(table, loop);
    for (MetricsConnection.CallTracker t : new MetricsConnection.CallTracker[] { METRICS.getGetTracker(), METRICS.getScanTracker(), METRICS.getMultiTracker(), METRICS.getAppendTracker(), METRICS.getDeleteTracker(), METRICS.getIncrementTracker(), METRICS.getPutTracker() }) {
        assertEquals("Failed to invoke callTimer on " + t, loop, t.callTimer.getCount());
        assertEquals("Failed to invoke reqHist on " + t, loop, t.reqHist.getCount());
        assertEquals("Failed to invoke respHist on " + t, loop, t.respHist.getCount());
    }
    RatioGauge executorMetrics = (RatioGauge) METRICS.getMetricRegistry().getMetrics().get(METRICS.getExecutorPoolName());
    RatioGauge metaMetrics = (RatioGauge) METRICS.getMetricRegistry().getMetrics().get(METRICS.getMetaPoolName());
    assertEquals(Ratio.of(0, 3).getValue(), executorMetrics.getValue(), 0);
    assertEquals(Double.NaN, metaMetrics.getValue(), 0);
}

