/**
 * See HBASE-21862, it is important to keep original exception type for connection exceptions.
 */
@Test
public void testWrapConnectionException() throws Exception {
    List<Throwable> exceptions = new ArrayList<>();
    for (Class<? extends Throwable> clazz : ClientExceptionsUtil.getConnectionExceptionTypes()) {
        exceptions.add(create(clazz));
    }
    Address addr = Address.fromParts("127.0.0.1", 12345);
    for (Throwable exception : exceptions) {
        if (exception instanceof TimeoutException) {
            assertThat(IPCUtil.wrapException(addr, null, exception), instanceOf(TimeoutIOException.class));
        } else {
            IOException ioe = IPCUtil.wrapException(addr, RegionInfoBuilder.FIRST_META_REGIONINFO, exception);
            // Assert that the exception contains the Region name if supplied. HBASE-25735.
            // Not all exceptions get the region stuffed into it.
            if (ioe.getMessage() != null) {
                assertTrue(ioe.getMessage().contains(RegionInfoBuilder.FIRST_META_REGIONINFO.getRegionNameAsString()));
            }
            assertThat(ioe, instanceOf(exception.getClass()));
        }
    }
}

@Test
public void testExecute() throws Exception {
    EventLoop eventLoop = new DefaultEventLoop();
    MutableInt executed = new MutableInt(0);
    MutableInt numStackTraceElements = new MutableInt(0);
    CompletableFuture<Void> future = new CompletableFuture<>();
    try {
        IPCUtil.execute(eventLoop, new Runnable() {

            @Override
            public void run() {
                int numElements = new Exception().getStackTrace().length;
                int depth = executed.getAndIncrement();
                if (depth <= IPCUtil.MAX_DEPTH) {
                    if (numElements <= numStackTraceElements.intValue()) {
                        future.completeExceptionally(new AssertionError("should call run directly but stack trace decreased from " + numStackTraceElements.intValue() + " to " + numElements));
                        return;
                    }
                    numStackTraceElements.setValue(numElements);
                    IPCUtil.execute(eventLoop, this);
                } else {
                    if (numElements >= numStackTraceElements.intValue()) {
                        future.completeExceptionally(new AssertionError("should call eventLoop.execute to prevent stack overflow but" + " stack trace increased from " + numStackTraceElements.intValue() + " to " + numElements));
                    } else {
                        future.complete(null);
                    }
                }
            }
        });
        FutureUtils.get(future);
    } finally {
        eventLoop.shutdownGracefully().get();
    }
}

@Test
public void testPrivateMethodExecutedInEventLoop() throws IllegalAccessException {
    assertThrows(AssertionError.class, () -> {
        assertTrue(false);
    });
    for (Method method : NettyRpcConnection.class.getDeclaredMethods()) {
        if (Modifier.isPrivate(method.getModifiers()) && !method.getName().contains("$")) {
            LOG.info("checking {}", method);
            method.setAccessible(true);
            // all private methods should be called inside the event loop thread, so calling it from
            // this thread will cause the "assert eventLoop.inEventLoop();" to fail
            try {
                // now there is no primitive parameters for the private methods so let's pass null
                method.invoke(CONN, new Object[method.getParameterCount()]);
                fail("should fail with AssertionError");
            } catch (InvocationTargetException e) {
                assertThat(e.getCause(), instanceOf(AssertionError.class));
            }
        }
    }
}

/**
 * test verifies that we honor the inherent value of an exception for isServerOverloaded. We don't
 * want a false value passed into RemoteWithExtrasExceptions to override the inherent value of an
 * exception if it's already true. This could be due to an out of date server not sending the
 * proto field we expect.
 */
@Test
public void itUsesExceptionDefaultValueForServerOverloaded() {
    // pass false for server overloaded, we still expect the exception to be true due to
    // the exception type
    RemoteWithExtrasException ex = new RemoteWithExtrasException(ServerOverloadedException.class.getName(), "server is overloaded", false, false);
    IOException result = ex.unwrapRemoteException();
    assertEquals(result.getClass(), ServerOverloadedException.class);
    assertTrue(((ServerOverloadedException) result).isServerOverloaded());
}

@Test
public void itUsesPassedServerOverloadedValue() {
    String exceptionClass = HBaseServerException.class.getName();
    String message = "server is overloaded";
    RemoteWithExtrasException ex = new RemoteWithExtrasException(exceptionClass, message, false, false);
    IOException result = ex.unwrapRemoteException();
    assertTrue(result instanceof HBaseServerException);
    assertFalse(((HBaseServerException) result).isServerOverloaded());
    // run again with true value passed in
    ex = new RemoteWithExtrasException(exceptionClass, message, false, true);
    result = ex.unwrapRemoteException();
    assertTrue(result instanceof HBaseServerException);
    // expect true this time
    assertTrue(((HBaseServerException) result).isServerOverloaded());
}

