    assertTrue(peerConfig.needToReplicate(TABLE_A));
    assertFalse(peerConfig.needToReplicate(TABLE_B));
    // 3. replicate_all flag is true, and config in excludeNamespaces
    // Exclude empty namespace set
    peerConfig = new ReplicationPeerConfig.ReplicationPeerConfigBuilderImpl().setReplicateAllUserTables(true).setExcludeNamespaces(Sets.newHashSet()).build();
    assertTrue(peerConfig.needToReplicate(TABLE_A));
    // Exclude namespace other
    peerConfig = new ReplicationPeerConfig.ReplicationPeerConfigBuilderImpl().setReplicateAllUserTables(true).setExcludeNamespaces(Sets.newHashSet(NAMESPACE_OTHER)).build();
    assertTrue(peerConfig.needToReplicate(TABLE_A));
    // Exclude namespace replication
    peerConfig = new ReplicationPeerConfig.ReplicationPeerConfigBuilderImpl().setReplicateAllUserTables(true).setExcludeNamespaces(Sets.newHashSet(NAMESPACE_REPLICATE)).build();
    assertFalse(peerConfig.needToReplicate(TABLE_A));
    // 4. replicate_all flag is true, and config excludeNamespaces and excludedTableCfs both
    // Namespaces config doesn't conflict with table-cfs config
