    tableCfs.put(TABLE_A, null);
    peerConfig = new ReplicationPeerConfig.ReplicationPeerConfigBuilderImpl().setReplicateAllUserTables(true).setExcludeNamespaces(Sets.newHashSet(NAMESPACE_REPLICATE)).setExcludeTableCFsMap(tableCfs).build();
    assertFalse(peerConfig.needToReplicate(TABLE_A));
