    ReplicationPeerConfig existingReplicationPeerConfig = getConfig(1);
    // custom config not present
    assertEquals(existingReplicationPeerConfig.getConfiguration().get(customPeerConfigKey), null);
    Configuration conf = new Configuration(CONF);
    conf.set(ReplicationPeerConfigUtil.HBASE_REPLICATION_PEER_BASE_CONFIG, customPeerConfigKey.concat("=").concat(customPeerConfigValue).concat(";").concat(customPeerConfigSecondKey).concat("=").concat(customPeerConfigSecondValue));
    ReplicationPeerConfig updatedReplicationPeerConfig = ReplicationPeerConfigUtil.updateReplicationBasePeerConfigs(conf, existingReplicationPeerConfig);
    // validates base configs are present in replicationPeerConfig
    assertEquals(customPeerConfigValue, updatedReplicationPeerConfig.getConfiguration().get(customPeerConfigKey));
    assertEquals(customPeerConfigSecondValue, updatedReplicationPeerConfig.getConfiguration().get(customPeerConfigSecondKey));
    // validates base configs get updated values even if config already present
    conf.unset(ReplicationPeerConfigUtil.HBASE_REPLICATION_PEER_BASE_CONFIG);
    conf.set(ReplicationPeerConfigUtil.HBASE_REPLICATION_PEER_BASE_CONFIG, customPeerConfigKey.concat("=").concat(customPeerConfigUpdatedValue).concat(";").concat(customPeerConfigSecondKey).concat("=").concat(customPeerConfigSecondUpdatedValue));
    ReplicationPeerConfig replicationPeerConfigAfterValueUpdate = ReplicationPeerConfigUtil.updateReplicationBasePeerConfigs(conf, updatedReplicationPeerConfig);
    assertEquals(customPeerConfigUpdatedValue, replicationPeerConfigAfterValueUpdate.getConfiguration().get(customPeerConfigKey));
    assertEquals(customPeerConfigSecondUpdatedValue, replicationPeerConfigAfterValueUpdate.getConfiguration().get(customPeerConfigSecondKey));
}

