@SuppressWarnings("unused")
@Test
public void testLeakDetection() throws InterruptedException {
    InternalLoggerFactory original = InternalLoggerFactory.getDefaultFactory();
    AtomicInteger leaksDetected = new AtomicInteger();
    InternalLoggerFactory.setDefaultFactory(new MockedLoggerFactory(leaksDetected));
    ResourceLeakDetector.setLevel(ResourceLeakDetector.Level.PARANOID);
    assertTrue(ResourceLeakDetector.isEnabled());
    try {
        int maxBuffersInPool = 10;
        int bufSize = 1024;
        int minSize = bufSize / 8;
        ByteBuffAllocator alloc = new ByteBuffAllocator(true, maxBuffersInPool, bufSize, minSize);
        // tracking leaks happens on creation of a RefCnt, through a call to detector.track().
        // If a leak occurs, but detector.track() is never called again, the leak will not be
        // realized. Further, causing a leak requires a GC event. So below we do some allocations,
        // cause some GC's, do more allocations, and then expect a leak to show up.
        // first allocate on-heap. we expect to not see a leak from this, because we
        // dont count on-heap references
        alloc.allocate(minSize - 1);
        System.gc();
        Thread.sleep(1000);
        // cause an allocation to trigger a leak detection, if there were one.
        // keep a reference so we don't trigger a leak right away from this.
        ByteBuff reference = alloc.allocate(minSize * 2);
        assertEquals(0, leaksDetected.get());
        // allocate, but don't keep a reference. this should cause a leak
        alloc.allocate(minSize * 2);
        System.gc();
        Thread.sleep(1000);
        // allocate again, this should cause the above leak to be detected
        alloc.allocate(minSize * 2);
        assertEquals(1, leaksDetected.get());
    } finally {
        InternalLoggerFactory.setDefaultFactory(original);
    }
}

@Test
public void testWrites() throws Exception {
    ByteBuffAllocator alloc = new ByteBuffAllocator(true, 3, 10, 10 / 6);
    ByteBufferListOutputStream bbos = new ByteBufferListOutputStream(alloc);
    // Write a byte
    bbos.write(2);
    // Write an int
    bbos.writeInt(100);
    // 6 bytes
    byte[] b = Bytes.toBytes("row123");
    bbos.write(b);
    assertEquals(2, bbos.allBufs.size());
    // Just use the 3rd BB from pool so that pabos, on request, wont get one
    ByteBuff bb1 = alloc.allocateOneBuffer();
    // 13 bytes
    ByteBuffer bb = ByteBuffer.wrap(Bytes.toBytes("row123_cf1_q1"));
    bbos.write(bb, 0, bb.capacity());
    bb1.release();
    bbos.writeInt(123);
    bbos.writeInt(124);
    assertEquals(0, alloc.getFreeBufferCount());
    List<ByteBuffer> allBufs = bbos.getByteBuffers();
    assertEquals(4, allBufs.size());
    assertEquals(4, bbos.allBufs.size());
    ByteBuffer b1 = allBufs.get(0);
    assertEquals(10, b1.remaining());
    assertEquals(2, b1.get());
    assertEquals(100, b1.getInt());
    byte[] bActual = new byte[b.length];
    // 5 bytes in 1st BB
    b1.get(bActual, 0, 5);
    ByteBuffer b2 = allBufs.get(1);
    assertEquals(10, b2.remaining());
    // Remaining 1 byte in 2nd BB
    b2.get(bActual, 5, 1);
    assertTrue(Bytes.equals(b, bActual));
    bActual = new byte[bb.capacity()];
    b2.get(bActual, 0, 9);
    ByteBuffer b3 = allBufs.get(2);
    assertEquals(8, b3.remaining());
    b3.get(bActual, 9, 4);
    assertTrue(ByteBufferUtils.equals(bb, 0, bb.capacity(), bActual, 0, bActual.length));
    assertEquals(123, b3.getInt());
    ByteBuffer b4 = allBufs.get(3);
    assertEquals(4, b4.remaining());
    assertEquals(124, b4.getInt());
    bbos.releaseResources();
    assertEquals(3, alloc.getFreeBufferCount());
}

