    ServerName sn3 = ServerName.valueOf("www.example.org", 1234, 56789);
    assertTrue(sn.equals(sn2));
    assertFalse(sn.equals(sn3));
    assertEquals(sn.hashCode(), sn2.hashCode());
    assertNotSame(sn.hashCode(), sn3.hashCode());
    assertEquals(sn.toString(), ServerName.valueOf("www.example.org", 1234, 5678).toString());
    assertEquals(sn.toString(), ServerName.valueOf("www.example.org:1234", 5678).toString());
    assertEquals("www.example.org" + ServerName.SERVERNAME_SEPARATOR + "1234" + ServerName.SERVERNAME_SEPARATOR + "5678", sn.toString());
}

