@Test
public void testSingleProxy() throws Throwable {
    Table table = util.getConnection().getTable(TEST_TABLE);
    Map<byte[], String> results = ping(table, null, null);
    // There are three regions so should get back three results.
    assertEquals(3, results.size());
    for (Map.Entry<byte[], String> e : results.entrySet()) {
        assertEquals("Invalid custom protocol response", "pong", e.getValue());
    }
    hello(table, "George", HELLO + "George");
    LOG.info("Did george");
    hello(table, null, "Who are you?");
    LOG.info("Who are you");
    hello(table, NOBODY, null);
    LOG.info(NOBODY);
    Map<byte[], Integer> intResults = table.coprocessorService(PingService.class, null, null, new Batch.Call<PingService, Integer>() {

        @Override
        public Integer call(PingService instance) throws IOException {
            CoprocessorRpcUtils.BlockingRpcCallback<CountResponse> rpcCallback = new CoprocessorRpcUtils.BlockingRpcCallback<>();
            instance.count(null, CountRequest.newBuilder().build(), rpcCallback);
            return rpcCallback.get().getCount();
        }
    });
    int count = -1;
    for (Map.Entry<byte[], Integer> e : intResults.entrySet()) {
        assertTrue(e.getValue() > 0);
        count = e.getValue();
    }
    final int diff = 5;
    intResults = table.coprocessorService(PingService.class, null, null, new Batch.Call<PingService, Integer>() {

        @Override
        public Integer call(PingService instance) throws IOException {
            CoprocessorRpcUtils.BlockingRpcCallback<IncrementCountResponse> rpcCallback = new CoprocessorRpcUtils.BlockingRpcCallback<>();
            instance.increment(null, IncrementCountRequest.newBuilder().setDiff(diff).build(), rpcCallback);
            return rpcCallback.get().getCount();
        }
    });
    // There are three regions so should get back three results.
    assertEquals(3, results.size());
    for (Map.Entry<byte[], Integer> e : intResults.entrySet()) {
        assertEquals(e.getValue().intValue(), count + diff);
    }
    table.close();
}

