        while (iterator.hasNext()) {
            LocatedFileStatus keyFileStatus = iterator.next();
            HFile.Reader reader = HFile.createReader(fs, keyFileStatus.getPath(), new CacheConfig(conf), true, conf);
            HFileScanner scanner = reader.getScanner(conf, false, false, false);
            kvCount += reader.getEntries();
            scanner.seekTo();
            long perKVSize = scanner.getCell().getSerializedSize();
            assertTrue("Data size of each file should not be too large.", perKVSize * reader.getEntries() <= hregionMaxFilesize);
        }
        assertEquals("Should write expected data in output file.", ROWSPERSPLIT, kvCount);
    }
}

