    for (ColumnFamilyDescriptor hcd : HBaseTestingUtil.generateColumnDescriptors()) {
        tableDescriptorBuilder.setColumnFamily(hcd);
    }
    // set up the table to return some mock keys
    setupMockStartKeys(regionLocator);
    try {
        // partial map red setup to get an operational writer for testing
        // We turn off the sequence file compression, because DefaultCodec
        // pollutes the GZip codec pool with an incompatible compressor.
        conf.set("io.seqfile.compression.type", "NONE");
        conf.set("hbase.fs.tmp.dir", dir.toString());
        // turn locality off to eliminate getRegionLocation fail-and-retry time when writing kvs
        conf.setBoolean(HFileOutputFormat2.LOCALITY_SENSITIVE_CONF_KEY, false);
        Job job = new Job(conf, "testLocalMRIncrementalLoad");
        job.setWorkingDirectory(util.getDataTestDirOnTestFS("testColumnFamilySettings"));
        setupRandomGeneratorMapper(job, false);
        HFileOutputFormat2.configureIncrementalLoad(job, table.getDescriptor(), regionLocator);
        FileOutputFormat.setOutputPath(job, dir);
        context = createTestTaskAttemptContext(job);
        HFileOutputFormat2 hof = new HFileOutputFormat2();
        writer = hof.getRecordWriter(context);
        // write out random rows
        writeRandomKeyValues(writer, context, tableDescriptorBuilder.build().getColumnFamilyNames(), ROWSPERSPLIT);
        writer.close(context);
        // Make sure that a directory was created for every CF
        FileSystem fs = dir.getFileSystem(conf);
        // commit so that the filesystem has one directory per column family
        hof.getOutputCommitter(context).commitTask(context);
        hof.getOutputCommitter(context).commitJob(context);
        FileStatus[] families = CommonFSUtils.listStatus(fs, dir, new FSUtils.FamilyDirFilter(fs));
        assertEquals(tableDescriptorBuilder.build().getColumnFamilies().length, families.length);
        for (FileStatus f : families) {
            String familyStr = f.getPath().getName();
            ColumnFamilyDescriptor hcd = tableDescriptorBuilder.build().getColumnFamily(Bytes.toBytes(familyStr));
            // verify that the compression on this file matches the configured
            // compression
            Path dataFilePath = fs.listStatus(f.getPath())[0].getPath();
            Reader reader = HFile.createReader(fs, dataFilePath, new CacheConfig(conf), true, conf);
            Map<byte[], byte[]> fileInfo = reader.getHFileInfo();
            byte[] bloomFilter = fileInfo.get(BLOOM_FILTER_TYPE_KEY);
            if (bloomFilter == null)
                bloomFilter = Bytes.toBytes("NONE");
            assertEquals("Incorrect bloom filter used for column family " + familyStr + "(reader: " + reader + ")", hcd.getBloomFilterType(), BloomType.valueOf(Bytes.toString(bloomFilter)));
            assertEquals("Incorrect compression used for column family " + familyStr + "(reader: " + reader + ")", hcd.getCompressionType(), reader.getFileContext().getCompression());
        }
    } finally {
        dir.getFileSystem(conf).delete(dir, true);
    }
}

/**
 * This test is to test the scenario happened in HBASE-6901. All files are bulk loaded and
 * excluded from minor compaction. Without the fix of HBASE-6901, an
 * ArrayIndexOutOfBoundsException will be thrown.
 */
@Ignore("Flakey: See HBASE-9051")
@Test
public void testExcludeAllFromMinorCompaction() throws Exception {
    Configuration conf = util.getConfiguration();
    conf.setInt("hbase.hstore.compaction.min", 2);
    generateRandomStartKeys(5);
    util.startMiniCluster();
    try (Connection conn = ConnectionFactory.createConnection();
        Admin admin = conn.getAdmin();
        Table table = util.createTable(TABLE_NAMES[0], FAMILIES);
        RegionLocator locator = conn.getRegionLocator(TABLE_NAMES[0])) {
        final FileSystem fs = util.getDFSCluster().getFileSystem();
        assertEquals("Should start with empty table", 0, util.countRows(table));
        // deep inspection: get the StoreFile dir
        final Path storePath = new Path(CommonFSUtils.getTableDir(CommonFSUtils.getRootDir(conf), TABLE_NAMES[0]), new Path(admin.getRegions(TABLE_NAMES[0]).get(0).getEncodedName(), Bytes.toString(FAMILIES[0])));
        assertEquals(0, fs.listStatus(storePath).length);
        // Generate two bulk load files
        conf.setBoolean("hbase.mapreduce.hfileoutputformat.compaction.exclude", true);
        for (int i = 0; i < 2; i++) {
            Path testDir = util.getDataTestDirOnTestFS("testExcludeAllFromMinorCompaction_" + i);
            runIncrementalPELoad(conf, Arrays.asList(new HFileOutputFormat2.TableInfo(table.getDescriptor(), conn.getRegionLocator(TABLE_NAMES[0]))), testDir, false);
            // Perform the actual load
            BulkLoadHFiles.create(conf).bulkLoad(table.getName(), testDir);
        }
        // Ensure data shows up
        int expectedRows = 2 * NMapInputFormat.getNumMapTasks(conf) * ROWSPERSPLIT;
        assertEquals("BulkLoadHFiles should put expected data in table", expectedRows, util.countRows(table));
        // should have a second StoreFile now
        assertEquals(2, fs.listStatus(storePath).length);
        // minor compactions shouldn't get rid of the file
        admin.compact(TABLE_NAMES[0]);
        try {
            quickPoll(new Callable<Boolean>() {

                @Override
                public Boolean call() throws Exception {
                    List<HRegion> regions = util.getMiniHBaseCluster().getRegions(TABLE_NAMES[0]);
                    for (HRegion region : regions) {
                        for (HStore store : region.getStores()) {
                            store.closeAndArchiveCompactedFiles();
                        }
                    }
                    return fs.listStatus(storePath).length == 1;
                }
            }, 5000);
            throw new IOException("SF# = " + fs.listStatus(storePath).length);
        } catch (AssertionError ae) {
            // this is expected behavior
        }
        // a major compaction should work though
        admin.majorCompact(TABLE_NAMES[0]);
        quickPoll(new Callable<Boolean>() {

            @Override
            public Boolean call() throws Exception {
                List<HRegion> regions = util.getMiniHBaseCluster().getRegions(TABLE_NAMES[0]);
                for (HRegion region : regions) {
                    for (HStore store : region.getStores()) {
                        store.closeAndArchiveCompactedFiles();
                    }
                }
                return fs.listStatus(storePath).length == 1;
            }
        }, 5000);
    } finally {
        util.shutdownMiniCluster();
    }
}

