    byte[] qualifierName = Bytes.toBytes("f1");
    Put put = new Put(Bytes.toBytes("r1"));
    long ts = EnvironmentEdgeManager.currentTime();
    put.addColumn(famName, qualifierName, ts + 1, Bytes.toBytes("v1002"));
