    assertFalse(tracker.isEmpty());
    assertTrue(tracker.isAllModified());
    tracker.update(procs[5]);
    assertFalse(tracker.isEmpty());
    assertTrue(tracker.isAllModified());
    for (int i = 0; i < 5; ++i) {
        tracker.delete(procs[i]);
        assertFalse(tracker.isEmpty());
        assertTrue(tracker.isAllModified());
    }
    tracker.delete(procs[5]);
    assertTrue(tracker.isEmpty());
}

