    ScanResponse resp = scan(req);
    assertTrue(resp.hasScannerId());
    long scannerId = resp.getScannerId();
    int nextCallSeq = 0;
    // test next
    for (int i = 0; i < COUNT / 2; i++) {
        req = RequestConverter.buildScanRequest(scannerId, 1, false, nextCallSeq++, false, false, -1);
