        // CheckAndIncrement with wrong value
        res = table.checkAndMutate(CheckAndMutate.newBuilder(ROWKEY).ifEquals(FAMILY, Bytes.toBytes("A"), Bytes.toBytes("b")).build(new Increment(ROWKEY).addColumn(FAMILY, Bytes.toBytes("B"), 1)));
