        res = table.checkAndMutate(CheckAndMutate.newBuilder(ROWKEY).ifMatches(new FilterList(new SingleColumnValueFilter(FAMILY, Bytes.toBytes("A"), CompareOperator.EQUAL, Bytes.toBytes("a")), new SingleColumnValueFilter(FAMILY, Bytes.toBytes("C"), CompareOperator.EQUAL, Bytes.toBytes("c")))).build(new Increment(ROWKEY).addColumn(FAMILY, Bytes.toBytes("B"), 2)));
        assertTrue(res.isSuccess());
        assertEquals(3, Bytes.toLong(res.getResult().getValue(FAMILY, Bytes.toBytes("B"))));
        result = table.get(new Get(ROWKEY).addColumn(FAMILY, Bytes.toBytes("B")));
        assertEquals(3, Bytes.toLong(result.getValue(FAMILY, Bytes.toBytes("B"))));
        // CheckAndIncrement with a filter and correct value
        res = table.checkAndMutate(CheckAndMutate.newBuilder(ROWKEY).ifMatches(new FilterList(new SingleColumnValueFilter(FAMILY, Bytes.toBytes("A"), CompareOperator.EQUAL, Bytes.toBytes("b")), new SingleColumnValueFilter(FAMILY, Bytes.toBytes("C"), CompareOperator.EQUAL, Bytes.toBytes("d")))).build(new Increment(ROWKEY).addColumn(FAMILY, Bytes.toBytes("B"), 2)));
        assertFalse(res.isSuccess());
        assertNull(res.getResult());
        result = table.get(new Get(ROWKEY).addColumn(FAMILY, Bytes.toBytes("B")));
        assertEquals(3, Bytes.toLong(result.getValue(FAMILY, Bytes.toBytes("B"))));
    }
}

