@Test
public void testCheckAndRowMutations() throws Throwable {
    final byte[] q1 = Bytes.toBytes("q1");
    final byte[] q2 = Bytes.toBytes("q2");
    final byte[] q3 = Bytes.toBytes("q3");
    final byte[] q4 = Bytes.toBytes("q4");
    final String v1 = "v1";
    try (Table table = createTable()) {
        // Initial values
        table.put(Arrays.asList(new Put(ROWKEY).addColumn(FAMILY, q2, Bytes.toBytes("toBeDeleted")), new Put(ROWKEY).addColumn(FAMILY, q3, Bytes.toBytes(5L)), new Put(ROWKEY).addColumn(FAMILY, q4, Bytes.toBytes("a"))));
        // Do CheckAndRowMutations
        CheckAndMutate checkAndMutate = CheckAndMutate.newBuilder(ROWKEY).ifNotExists(FAMILY, q1).build(new RowMutations(ROWKEY).add(Arrays.asList(new Put(ROWKEY).addColumn(FAMILY, q1, Bytes.toBytes(v1)), new Delete(ROWKEY).addColumns(FAMILY, q2), new Increment(ROWKEY).addColumn(FAMILY, q3, 1), new Append(ROWKEY).addColumn(FAMILY, q4, Bytes.toBytes("b")))));
        CheckAndMutateResult result = table.checkAndMutate(checkAndMutate);
        assertTrue(result.isSuccess());
        assertEquals(6L, Bytes.toLong(result.getResult().getValue(FAMILY, q3)));
        assertEquals("ab", Bytes.toString(result.getResult().getValue(FAMILY, q4)));
        // Verify the value
        Result r = table.get(new Get(ROWKEY));
        assertEquals(v1, Bytes.toString(r.getValue(FAMILY, q1)));
        assertNull(r.getValue(FAMILY, q2));
        assertEquals(6L, Bytes.toLong(r.getValue(FAMILY, q3)));
        assertEquals("ab", Bytes.toString(r.getValue(FAMILY, q4)));
        // Do CheckAndRowMutations again
        checkAndMutate = CheckAndMutate.newBuilder(ROWKEY).ifNotExists(FAMILY, q1).build(new RowMutations(ROWKEY).add(Arrays.asList(new Delete(ROWKEY).addColumns(FAMILY, q1), new Put(ROWKEY).addColumn(FAMILY, q2, Bytes.toBytes(v1)), new Increment(ROWKEY).addColumn(FAMILY, q3, 1), new Append(ROWKEY).addColumn(FAMILY, q4, Bytes.toBytes("b")))));
        result = table.checkAndMutate(checkAndMutate);
        assertFalse(result.isSuccess());
        assertNull(result.getResult());
        // Verify the value
        r = table.get(new Get(ROWKEY));
        assertEquals(v1, Bytes.toString(r.getValue(FAMILY, q1)));
        assertNull(r.getValue(FAMILY, q2));
        assertEquals(6L, Bytes.toLong(r.getValue(FAMILY, q3)));
        assertEquals("ab", Bytes.toString(r.getValue(FAMILY, q4)));
    }
}

