@Test
public void testRetryTimeJitter() {
    long[] retries = new long[200];
    // Larger number than reality to help test randomness.
    long baseTime = 1000000;
    long maxTimeExpected = (long) (baseTime * 1.01f);
    for (int i = 0; i < retries.length; i++) {
        retries[i] = ConnectionUtils.getPauseTime(baseTime, 0);
    }
    Set<Long> retyTimeSet = new TreeSet<>();
    for (long l : retries) {
        /* make sure that there is some jitter but only 1% */
        assertTrue(l >= baseTime);
        assertTrue(l <= maxTimeExpected);
        // Add the long to the set
        retyTimeSet.add(l);
    }
    // Make sure that most are unique. some overlap will happen
    assertTrue(retyTimeSet.size() > (retries.length * 0.80));
}

@Test
public void testGetPauseTime() {
    long pauseTime;
    long baseTime = 100;
    pauseTime = ConnectionUtils.getPauseTime(baseTime, -1);
    assertTrue(pauseTime >= (baseTime * HConstants.RETRY_BACKOFF[0]));
    assertTrue(pauseTime <= (baseTime * HConstants.RETRY_BACKOFF[0] * 1.01f));
    for (int i = 0; i < HConstants.RETRY_BACKOFF.length; i++) {
        pauseTime = ConnectionUtils.getPauseTime(baseTime, i);
        assertTrue(pauseTime >= (baseTime * HConstants.RETRY_BACKOFF[i]));
        assertTrue(pauseTime <= (baseTime * HConstants.RETRY_BACKOFF[i] * 1.01f));
    }
    int length = HConstants.RETRY_BACKOFF.length;
    pauseTime = ConnectionUtils.getPauseTime(baseTime, length);
    assertTrue(pauseTime >= (baseTime * HConstants.RETRY_BACKOFF[length - 1]));
    assertTrue(pauseTime <= (baseTime * HConstants.RETRY_BACKOFF[length - 1] * 1.01f));
}

@Test
public void testDropTimeoutRequest() throws Exception {
    // Simulate the situation that the server is slow and client retries for several times because
    // of timeout. When a request can be handled after waiting in the queue, we will drop it if
    // it has been considered as timeout at client. If we don't drop it, the server will waste time
    // on handling timeout requests and finally all requests timeout and client throws exception.
    TableDescriptorBuilder builder = TableDescriptorBuilder.newBuilder(TableName.valueOf(name.getMethodName()));
    builder.setCoprocessor(SleepLongerAtFirstCoprocessor.class.getName());
    ColumnFamilyDescriptor cfd = ColumnFamilyDescriptorBuilder.newBuilder(FAM_NAM).build();
    builder.setColumnFamily(cfd);
    TableDescriptor td = builder.build();
    try (Admin admin = TEST_UTIL.getConnection().getAdmin()) {
        admin.createTable(td);
    }
    TableBuilder tb = TEST_UTIL.getConnection().getTableBuilder(td.getTableName(), null);
    tb.setReadRpcTimeout(SleepLongerAtFirstCoprocessor.SLEEP_TIME * 2);
    tb.setWriteRpcTimeout(SleepLongerAtFirstCoprocessor.SLEEP_TIME * 2);
    try (Table table = tb.build()) {
        table.get(new Get(FAM_NAM));
    }
}

