@Test
public void testDeleteFamilyVersion() throws Exception {
    try (Admin admin = TEST_UTIL.getAdmin()) {
        final TableName tableName = name.getTableName();
        byte[][] QUALIFIERS = makeNAscii(QUALIFIER, 1);
        byte[][] VALUES = makeN(VALUE, 5);
        long[] ts = { 1000, 2000, 3000, 4000, 5000 };
        try (Table ht = TEST_UTIL.createTable(tableName, FAMILY, 5)) {
            Put put = new Put(ROW);
            for (int q = 0; q < 1; q++) {
                for (int t = 0; t < 5; t++) {
                    put.addColumn(FAMILY, QUALIFIERS[q], ts[t], VALUES[t]);
                }
            }
            ht.put(put);
            admin.flush(tableName);
            Delete delete = new Delete(ROW);
            // delete version '2000'
            delete.addFamilyVersion(FAMILY, ts[1]);
            // delete version '4000'
            delete.addFamilyVersion(FAMILY, ts[3]);
            ht.delete(delete);
            admin.flush(tableName);
            for (int i = 0; i < 1; i++) {
                Get get = new Get(ROW);
                get.addColumn(FAMILY, QUALIFIERS[i]);
                get.readVersions(Integer.MAX_VALUE);
                Result result = ht.get(get);
                // verify version '1000'/'3000'/'5000' remains for all columns
                assertNResult(result, ROW, FAMILY, QUALIFIERS[i], new long[] { ts[0], ts[2], ts[4] }, new byte[][] { VALUES[0], VALUES[2], VALUES[4] }, 0, 2);
            }
        }
    }
}

@Test
public void testDeleteFamilyVersionWithOtherDeletes() throws Exception {
    final TableName tableName = name.getTableName();
    byte[][] QUALIFIERS = makeNAscii(QUALIFIER, 5);
    byte[][] VALUES = makeN(VALUE, 5);
    long[] ts = { 1000, 2000, 3000, 4000, 5000 };
    try (Admin admin = TEST_UTIL.getAdmin();
        Table ht = TEST_UTIL.createTable(tableName, FAMILY, 5)) {
        Put put;
        Result result;
        Get get;
        Delete delete = null;
        // 1. put on ROW
        put = new Put(ROW);
        for (int q = 0; q < 5; q++) {
            for (int t = 0; t < 5; t++) {
                put.addColumn(FAMILY, QUALIFIERS[q], ts[t], VALUES[t]);
            }
        }
        ht.put(put);
        admin.flush(tableName);
        // 2. put on ROWS[0]
        byte[] ROW2 = Bytes.toBytes("myRowForTest");
        put = new Put(ROW2);
        for (int q = 0; q < 5; q++) {
            for (int t = 0; t < 5; t++) {
                put.addColumn(FAMILY, QUALIFIERS[q], ts[t], VALUES[t]);
            }
        }
        ht.put(put);
        admin.flush(tableName);
        // 3. delete on ROW
        delete = new Delete(ROW);
        // delete version <= 2000 of all columns
        // note: addFamily must be the first since it will mask
        // the subsequent other type deletes!
        delete.addFamily(FAMILY, ts[1]);
        // delete version '4000' of all columns
        delete.addFamilyVersion(FAMILY, ts[3]);
        // delete version <= 3000 of column 0
        delete.addColumns(FAMILY, QUALIFIERS[0], ts[2]);
        // delete version <= 5000 of column 2
        delete.addColumns(FAMILY, QUALIFIERS[2], ts[4]);
        // delete version 5000 of column 4
        delete.addColumn(FAMILY, QUALIFIERS[4], ts[4]);
        ht.delete(delete);
        admin.flush(tableName);
        // 4. delete on ROWS[0]
        delete = new Delete(ROW2);
        // delete version '2000'
        delete.addFamilyVersion(FAMILY, ts[1]);
        // delete version '4000'
        delete.addFamilyVersion(FAMILY, ts[3]);
        ht.delete(delete);
        admin.flush(tableName);
        // 5. check ROW
        get = new Get(ROW);
        get.addColumn(FAMILY, QUALIFIERS[0]);
        get.readVersions(Integer.MAX_VALUE);
        result = ht.get(get);
        assertNResult(result, ROW, FAMILY, QUALIFIERS[0], new long[] { ts[4] }, new byte[][] { VALUES[4] }, 0, 0);
        get = new Get(ROW);
        get.addColumn(FAMILY, QUALIFIERS[1]);
        get.readVersions(Integer.MAX_VALUE);
        result = ht.get(get);
        assertNResult(result, ROW, FAMILY, QUALIFIERS[1], new long[] { ts[2], ts[4] }, new byte[][] { VALUES[2], VALUES[4] }, 0, 1);
        get = new Get(ROW);
        get.addColumn(FAMILY, QUALIFIERS[2]);
        get.readVersions(Integer.MAX_VALUE);
        result = ht.get(get);
        assertEquals(0, result.size());
        get = new Get(ROW);
        get.addColumn(FAMILY, QUALIFIERS[3]);
        get.readVersions(Integer.MAX_VALUE);
        result = ht.get(get);
        assertNResult(result, ROW, FAMILY, QUALIFIERS[3], new long[] { ts[2], ts[4] }, new byte[][] { VALUES[2], VALUES[4] }, 0, 1);
        get = new Get(ROW);
        get.addColumn(FAMILY, QUALIFIERS[4]);
        get.readVersions(Integer.MAX_VALUE);
        result = ht.get(get);
        assertNResult(result, ROW, FAMILY, QUALIFIERS[4], new long[] { ts[2] }, new byte[][] { VALUES[2] }, 0, 0);
        // 6. check ROWS[0]
        for (int i = 0; i < 5; i++) {
            get = new Get(ROW2);
            get.addColumn(FAMILY, QUALIFIERS[i]);
            get.readVersions(Integer.MAX_VALUE);
            result = ht.get(get);
            // verify version '1000'/'3000'/'5000' remains for all columns
            assertNResult(result, ROW2, FAMILY, QUALIFIERS[i], new long[] { ts[0], ts[2], ts[4] }, new byte[][] { VALUES[0], VALUES[2], VALUES[4] }, 0, 2);
        }
    }
}

