@Test
public void testBatchWithRowMutation() throws Exception {
    LOG.info("Starting testBatchWithRowMutation");
    byte[][] QUALIFIERS = new byte[][] { Bytes.toBytes("a"), Bytes.toBytes("b") };
    try (Table table = TEST_UTIL.createTable(tableName, new byte[][] { FAMILY })) {
        TEST_UTIL.waitTableAvailable(tableName, WAITTABLE_MILLIS);
        RowMutations arm = RowMutations.of(Collections.singletonList(new Put(ROW).addColumn(FAMILY, QUALIFIERS[0], VALUE)));
        Object[] batchResult = new Object[1];
        table.batch(Arrays.asList(arm), batchResult);
        Get g = new Get(ROW);
        Result r = table.get(g);
        assertEquals(0, Bytes.compareTo(VALUE, r.getValue(FAMILY, QUALIFIERS[0])));
        arm = RowMutations.of(Arrays.asList(new Put(ROW).addColumn(FAMILY, QUALIFIERS[1], VALUE), new Delete(ROW).addColumns(FAMILY, QUALIFIERS[0])));
        table.batch(Arrays.asList(arm), batchResult);
        r = table.get(g);
        assertEquals(0, Bytes.compareTo(VALUE, r.getValue(FAMILY, QUALIFIERS[1])));
        assertNull(r.getValue(FAMILY, QUALIFIERS[0]));
        // Test that we get the correct remote exception for RowMutations from batch()
        try {
            arm = RowMutations.of(Collections.singletonList(new Put(ROW).addColumn(new byte[] { 'b', 'o', 'g', 'u', 's' }, QUALIFIERS[0], VALUE)));
            table.batch(Arrays.asList(arm), batchResult);
            fail("Expected RetriesExhaustedWithDetailsException with NoSuchColumnFamilyException");
        } catch (RetriesExhaustedException e) {
            String msg = e.getMessage();
            assertTrue(msg.contains("NoSuchColumnFamilyException"));
        }
    }
}

@Test
public void testBatchWithCheckAndMutate() throws Exception {
    try (Table table = TEST_UTIL.createTable(tableName, new byte[][] { FAMILY })) {
        byte[] row1 = Bytes.toBytes("row1");
        byte[] row2 = Bytes.toBytes("row2");
        byte[] row3 = Bytes.toBytes("row3");
        byte[] row4 = Bytes.toBytes("row4");
        byte[] row5 = Bytes.toBytes("row5");
        byte[] row6 = Bytes.toBytes("row6");
        byte[] row7 = Bytes.toBytes("row7");
        table.put(Arrays.asList(new Put(row1).addColumn(FAMILY, Bytes.toBytes("A"), Bytes.toBytes("a")), new Put(row2).addColumn(FAMILY, Bytes.toBytes("B"), Bytes.toBytes("b")), new Put(row3).addColumn(FAMILY, Bytes.toBytes("C"), Bytes.toBytes("c")), new Put(row4).addColumn(FAMILY, Bytes.toBytes("D"), Bytes.toBytes("d")), new Put(row5).addColumn(FAMILY, Bytes.toBytes("E"), Bytes.toBytes("e")), new Put(row6).addColumn(FAMILY, Bytes.toBytes("F"), Bytes.toBytes(10L)), new Put(row7).addColumn(FAMILY, Bytes.toBytes("G"), Bytes.toBytes("g"))));
        CheckAndMutate checkAndMutate1 = CheckAndMutate.newBuilder(row1).ifEquals(FAMILY, Bytes.toBytes("A"), Bytes.toBytes("a")).build(new RowMutations(row1).add(new Put(row1).addColumn(FAMILY, Bytes.toBytes("B"), Bytes.toBytes("g"))).add(new Delete(row1).addColumns(FAMILY, Bytes.toBytes("A"))).add(new Increment(row1).addColumn(FAMILY, Bytes.toBytes("C"), 3L)).add(new Append(row1).addColumn(FAMILY, Bytes.toBytes("D"), Bytes.toBytes("d"))));
        Get get = new Get(row2).addColumn(FAMILY, Bytes.toBytes("B"));
        RowMutations mutations = new RowMutations(row3).add(new Delete(row3).addColumns(FAMILY, Bytes.toBytes("C"))).add(new Put(row3).addColumn(FAMILY, Bytes.toBytes("F"), Bytes.toBytes("f"))).add(new Increment(row3).addColumn(FAMILY, Bytes.toBytes("A"), 5L)).add(new Append(row3).addColumn(FAMILY, Bytes.toBytes("B"), Bytes.toBytes("b")));
        CheckAndMutate checkAndMutate2 = CheckAndMutate.newBuilder(row4).ifEquals(FAMILY, Bytes.toBytes("D"), Bytes.toBytes("a")).build(new Put(row4).addColumn(FAMILY, Bytes.toBytes("E"), Bytes.toBytes("h")));
        Put put = new Put(row5).addColumn(FAMILY, Bytes.toBytes("E"), Bytes.toBytes("f"));
        CheckAndMutate checkAndMutate3 = CheckAndMutate.newBuilder(row6).ifEquals(FAMILY, Bytes.toBytes("F"), Bytes.toBytes(10L)).build(new Increment(row6).addColumn(FAMILY, Bytes.toBytes("F"), 1));
        CheckAndMutate checkAndMutate4 = CheckAndMutate.newBuilder(row7).ifEquals(FAMILY, Bytes.toBytes("G"), Bytes.toBytes("g")).build(new Append(row7).addColumn(FAMILY, Bytes.toBytes("G"), Bytes.toBytes("g")));
        List<Row> actions = Arrays.asList(checkAndMutate1, get, mutations, checkAndMutate2, put, checkAndMutate3, checkAndMutate4);
        Object[] results = new Object[actions.size()];
        table.batch(actions, results);
        CheckAndMutateResult checkAndMutateResult = (CheckAndMutateResult) results[0];
        assertTrue(checkAndMutateResult.isSuccess());
        assertEquals(3L, Bytes.toLong(checkAndMutateResult.getResult().getValue(FAMILY, Bytes.toBytes("C"))));
        assertEquals("d", Bytes.toString(checkAndMutateResult.getResult().getValue(FAMILY, Bytes.toBytes("D"))));
        assertEquals("b", Bytes.toString(((Result) results[1]).getValue(FAMILY, Bytes.toBytes("B"))));
        Result result = (Result) results[2];
        assertTrue(result.getExists());
        assertEquals(5L, Bytes.toLong(result.getValue(FAMILY, Bytes.toBytes("A"))));
        assertEquals("b", Bytes.toString(result.getValue(FAMILY, Bytes.toBytes("B"))));
        checkAndMutateResult = (CheckAndMutateResult) results[3];
        assertFalse(checkAndMutateResult.isSuccess());
        assertNull(checkAndMutateResult.getResult());
        assertTrue(((Result) results[4]).isEmpty());
        checkAndMutateResult = (CheckAndMutateResult) results[5];
        assertTrue(checkAndMutateResult.isSuccess());
        assertEquals(11, Bytes.toLong(checkAndMutateResult.getResult().getValue(FAMILY, Bytes.toBytes("F"))));
        checkAndMutateResult = (CheckAndMutateResult) results[6];
        assertTrue(checkAndMutateResult.isSuccess());
        assertEquals("gg", Bytes.toString(checkAndMutateResult.getResult().getValue(FAMILY, Bytes.toBytes("G"))));
        result = table.get(new Get(row1));
        assertEquals("g", Bytes.toString(result.getValue(FAMILY, Bytes.toBytes("B"))));
        assertNull(result.getValue(FAMILY, Bytes.toBytes("A")));
        assertEquals(3L, Bytes.toLong(result.getValue(FAMILY, Bytes.toBytes("C"))));
        assertEquals("d", Bytes.toString(result.getValue(FAMILY, Bytes.toBytes("D"))));
        result = table.get(new Get(row3));
        assertNull(result.getValue(FAMILY, Bytes.toBytes("C")));
        assertEquals("f", Bytes.toString(result.getValue(FAMILY, Bytes.toBytes("F"))));
        assertNull(Bytes.toString(result.getValue(FAMILY, Bytes.toBytes("C"))));
