                put.addColumn(FAMILY, QUALIFIERS[j], QUALIFIERS[j]);
            }
            assertEquals("Put expected to contain " + numColsPerRow + " columns but " + "only contains " + put.size(), put.size(), numColsPerRow);
            ht.put(put);
        }
        // Get a row
        Get get = new Get(ROWS[numRows - 1]);
        Result result = ht.get(get);
        assertNumKeys(result, numColsPerRow);
        Cell[] keys = result.rawCells();
        for (int i = 0; i < result.size(); i++) {
            assertKey(keys[i], ROWS[numRows - 1], FAMILY, QUALIFIERS[i], QUALIFIERS[i]);
        }
        // Scan the rows
        Scan scan = new Scan();
        try (ResultScanner scanner = ht.getScanner(scan)) {
            int rowCount = 0;
            while ((result = scanner.next()) != null) {
                assertNumKeys(result, numColsPerRow);
                Cell[] kvs = result.rawCells();
                for (int i = 0; i < numColsPerRow; i++) {
                    assertKey(kvs[i], ROWS[rowCount], FAMILY, QUALIFIERS[i], QUALIFIERS[i]);
                }
                rowCount++;
            }
            assertEquals("Expected to scan " + numRows + " rows but actually scanned " + rowCount + " rows", rowCount, numRows);
        }
        // flush and try again
        TEST_UTIL.flush();
        // Get a row
        get = new Get(ROWS[numRows - 1]);
        result = ht.get(get);
        assertNumKeys(result, numColsPerRow);
        keys = result.rawCells();
        for (int i = 0; i < result.size(); i++) {
            assertKey(keys[i], ROWS[numRows - 1], FAMILY, QUALIFIERS[i], QUALIFIERS[i]);
        }
        // Scan the rows
        scan = new Scan();
        try (ResultScanner scanner = ht.getScanner(scan)) {
            int rowCount = 0;
            while ((result = scanner.next()) != null) {
                assertNumKeys(result, numColsPerRow);
                Cell[] kvs = result.rawCells();
                for (int i = 0; i < numColsPerRow; i++) {
                    assertKey(kvs[i], ROWS[rowCount], FAMILY, QUALIFIERS[i], QUALIFIERS[i]);
                }
                rowCount++;
            }
            assertEquals("Expected to scan " + numRows + " rows but actually scanned " + rowCount + " rows", rowCount, numRows);
        }
    }
}

