    assertTrue(((CoprocessorImpl) c).wasOpened());
    assertTrue(((CoprocessorImpl) c).wasClosed());
    assertTrue(((CoprocessorImpl) c).wasFlushed());
    assertTrue(((CoprocessorImpl) c).wasCompacted());
