@Test
public void testRegionObserverCompactionTimeStacking() throws Exception {
    // setup a mini cluster so we can do a real compaction on a region
    Configuration conf = UTIL.getConfiguration();
    conf.setClass(HConstants.REGION_IMPL, CompactionCompletionNotifyingRegion.class, HRegion.class);
    conf.setInt("hbase.hstore.compaction.min", 2);
    UTIL.startMiniCluster();
    byte[] ROW = Bytes.toBytes("testRow");
    byte[] A = Bytes.toBytes("A");
    TableDescriptor tableDescriptor = TableDescriptorBuilder.newBuilder(TableName.valueOf(name.getMethodName())).setColumnFamily(ColumnFamilyDescriptorBuilder.of(A)).setCoprocessor(CoprocessorDescriptorBuilder.newBuilder(EmptyRegionObsever.class.getName()).setJarPath(null).setPriority(Coprocessor.PRIORITY_USER).setProperties(Collections.emptyMap()).build()).setCoprocessor(CoprocessorDescriptorBuilder.newBuilder(NoDataFromCompaction.class.getName()).setJarPath(null).setPriority(Coprocessor.PRIORITY_HIGHEST).setProperties(Collections.emptyMap()).build()).build();
    Admin admin = UTIL.getAdmin();
