@Test
public void testScanWithLimit() {
    int kv_number = 0;
    try {
        Scan scan = new Scan();
        // set batch number as 2, which means each Result should contain 2 KVs at most
        scan.setBatch(2);
        SingleColumnValueFilter filter = new SingleColumnValueFilter(Bytes.toBytes(columnFamily), Bytes.toBytes("c5"), CompareOperator.EQUAL, new SubstringComparator("2_c5"));
        // add filter after batch defined
        scan.setFilter(filter);
        Table table = openTable(tableName);
        ResultScanner scanner = table.getScanner(scan);
        // Expect to get following row
        // row2 => <f1:c1, 2_c1>, <f1:c2, 2_c2>,
        // row2 => <f1:c3, 2_c3>, <f1:c4, 2_c4>,
        // row2 => <f1:c5, 2_c5>
        for (Result result : scanner) {
            for (Cell kv : result.listCells()) {
                kv_number++;
                LOG.debug(kv_number + ". kv: " + kv);
            }
        }
        scanner.close();
        table.close();
    } catch (Exception e) {
        // no correct result is expected
        assertNotNull("No IncompatibleFilterException catched", e);
    }
    LOG.debug("check the fetched kv number");
    assertEquals("We should not get result(s) returned.", 0, kv_number);
}

@Test
public void testFilterWrapper() {
    int kv_number = 0;
    int row_number = 0;
    try {
        Scan scan = new Scan();
        List<Filter> fs = new ArrayList<>();
        DependentColumnFilter f1 = new DependentColumnFilter(Bytes.toBytes("f1"), Bytes.toBytes("c5"), true, CompareOperator.EQUAL, new SubstringComparator("c5"));
        PageFilter f2 = new PageFilter(2);
        fs.add(f1);
        fs.add(f2);
        FilterList filter = new FilterList(fs);
        scan.setFilter(filter);
        Table table = connection.getTable(name);
        ResultScanner scanner = table.getScanner(scan);
        // row2 (c1-c4) and row3(c1-c4) are returned
        for (Result result : scanner) {
            row_number++;
            for (Cell kv : result.listCells()) {
                LOG.debug(kv_number + ". kv: " + kv);
                kv_number++;
                assertEquals("Returned row is not correct", Bytes.toString(CellUtil.cloneRow(kv)), "row" + (row_number + 1));
            }
        }
        scanner.close();
        table.close();
    } catch (Exception e) {
        // no correct result is expected
        assertNull("Exception happens in scan", e);
    }
    LOG.debug("check the fetched kv number");
    assertEquals("We should get 8 results returned.", 8, kv_number);
    assertEquals("We should get 2 rows returned", 2, row_number);
}

@Test
public void Test() throws Exception {
    String cf = "f";
    Table ht = TEST_UTIL.createTable(TableName.valueOf(name.getMethodName()), Bytes.toBytes(cf), Integer.MAX_VALUE);
    // 10 byte row key - (2 bytes 4 bytes 4 bytes)
    // 4 byte qualifier
    // 4 byte value
    for (int i1 = 0; i1 < 2; i1++) {
        for (int i2 = 0; i2 < 5; i2++) {
            byte[] rk = new byte[10];
            ByteBuffer buf = ByteBuffer.wrap(rk);
            buf.clear();
            buf.putShort((short) 2);
            buf.putInt(i1);
            buf.putInt(i2);
            for (int c = 0; c < 5; c++) {
                byte[] cq = new byte[4];
                Bytes.putBytes(cq, 0, Bytes.toBytes(c), 0, 4);
                Put p = new Put(rk);
                p.setDurability(Durability.SKIP_WAL);
                p.addColumn(Bytes.toBytes(cf), cq, Bytes.toBytes(c));
                ht.put(p);
                LOG.info("Inserting: rk: " + Bytes.toStringBinary(rk) + " cq: " + Bytes.toStringBinary(cq));
            }
        }
    }
    TEST_UTIL.flush();
    // test passes
    runTest(ht, 0, 10);
    // test fails
    runTest(ht, 1, 8);
}

