@Test
public void testReverseMultiRowRangeFilterWithinTable() throws IOException {
    tableName = TableName.valueOf(name.getMethodName());
    Table ht = TEST_UTIL.createTable(tableName, family);
    generateRows(numRows, ht, family, qf, value);
    Scan scan = new Scan();
    scan.setReversed(true);
    List<RowRange> ranges = Arrays.asList(new RowRange(Bytes.toBytes(20), true, Bytes.toBytes(30), true), new RowRange(Bytes.toBytes(50), true, Bytes.toBytes(60), true));
    MultiRowRangeFilter filter = new MultiRowRangeFilter(ranges);
    scan.setFilter(filter);
    List<Integer> expectedResults = new ArrayList<>();
    for (int i = 60; i >= 50; i--) {
        expectedResults.add(i);
    }
    for (int i = 30; i >= 20; i--) {
        expectedResults.add(i);
    }
    List<Cell> results = getResults(ht, scan);
    List<Integer> actualResults = new ArrayList<>();
    StringBuilder sb = new StringBuilder();
    for (Cell result : results) {
        int observedValue = Bytes.toInt(result.getRowArray(), result.getRowOffset(), result.getRowLength());
        actualResults.add(observedValue);
        if (sb.length() > 0) {
            sb.append(", ");
        }
        sb.append(observedValue);
    }
    assertEquals("Saw results: " + sb.toString(), 22, results.size());
}

