        // The interceptor is not set in this test, so we get the raw list at this point
        LocatedBlocks lbs;
        final long max = EnvironmentEdgeManager.currentTime() + 10000;
        do {
            lbs = getNamenode(dfs.getClient()).getBlockLocations(fileName, 0, 1);
