    BlockCacheKey bucketCacheKey = bucketCache1.backingMap.entrySet().iterator().next().getKey();
    bucketCache1.evictBlock(bucketCacheKey);
    assertFalse(bucketCache1.fullyCachedFiles.containsKey(storeFile.getName()));
}

