    CachedBlock cb10 = new CachedBlock(1500, "cb10", 10);
    LruCachedBlockQueue queue = new LruCachedBlockQueue(10000, 1000);
    queue.add(cb1);
    queue.add(cb2);
    queue.add(cb3);
    queue.add(cb4);
    queue.add(cb5);
    queue.add(cb6);
    queue.add(cb7);
    queue.add(cb8);
