            } catch (Exception e) {
                assertThat(e, new IsThrowableMatching().withInstanceOf(IllegalArgumentException.class));
            }
            assertEquals(0, consumer.getItemsRead());
        }
        c.restore();
        c.write(HFileBlock.Header.ON_DISK_SIZE_WITHOUT_HEADER_INDEX, ByteBuffer.wrap(Bytes.toBytes(Integer.MAX_VALUE)));
