/**
 * This test is for HBASE-27940, which midkey metadata in root index block would always be ignored
 * by {@link BlockIndexReader#readMultiLevelIndexRoot}.
 */
@Test
public void testMidKeyReadSuccessfullyFromRootIndexBlock() throws IOException {
    conf.setInt(HFileBlockIndex.MAX_CHUNK_SIZE_KEY, 128);
    Path hfilePath = new Path(TEST_UTIL.getDataTestDir(), "testMidKeyReadSuccessfullyFromRootIndexBlock");
    Compression.Algorithm compressAlgo = Compression.Algorithm.NONE;
    int entryCount = 50000;
    HFileContext context = new HFileContextBuilder().withBlockSize(4096).withIncludesTags(false).withDataBlockEncoding(DataBlockEncoding.NONE).withCompression(compressAlgo).build();
    try (HFile.Writer writer = new HFile.WriterFactory(conf, new CacheConfig(conf)).withPath(fs, hfilePath).withFileContext(context).create()) {
        List<KeyValue> keyValues = new ArrayList<>(entryCount);
        for (int i = 0; i < entryCount; ++i) {
            byte[] keyBytes = RandomKeyValueUtil.randomOrderedKey(RNG, i);
            // A random-length random value.
            byte[] valueBytes = RandomKeyValueUtil.randomValue(RNG);
            KeyValue keyValue = new KeyValue(keyBytes, null, null, HConstants.LATEST_TIMESTAMP, valueBytes);
            writer.append(keyValue);
            keyValues.add(keyValue);
        }
    }
    try (FSDataInputStream fsdis = fs.open(hfilePath)) {
        long fileSize = fs.getFileStatus(hfilePath).getLen();
        FixedFileTrailer trailer = FixedFileTrailer.readFromStream(fsdis, fileSize);
        assertEquals(3, trailer.getMajorVersion());
        assertEquals(entryCount, trailer.getEntryCount());
        HFileContext meta = new HFileContextBuilder().withCompression(compressAlgo).withIncludesMvcc(false).withIncludesTags(false).withDataBlockEncoding(DataBlockEncoding.NONE).withHBaseCheckSum(true).build();
        ReaderContext readerContext = new ReaderContextBuilder().withInputStreamWrapper(new FSDataInputStreamWrapper(fsdis)).withFilePath(hfilePath).withFileSystem(fs).withFileSize(fileSize).build();
        HFileBlock.FSReader blockReader = new HFileBlock.FSReaderImpl(readerContext, meta, ByteBuffAllocator.HEAP, conf);
        MyEncoder encoder = new MyEncoder();
        HFileBlockIndex.CellBasedKeyBlockIndexReaderV2 dataBlockIndexReader = new HFileBlockIndex.CellBasedKeyBlockIndexReaderV2(trailer.createComparator(), trailer.getNumDataIndexLevels(), encoder);
        HFileBlock.BlockIterator blockIter = blockReader.blockRange(trailer.getLoadOnOpenDataOffset(), fileSize - trailer.getTrailerSize());
        // Data index. We also read statistics about the block index written after
        // the root level.
        dataBlockIndexReader.readMultiLevelIndexRoot(blockIter.nextBlockWithBlockType(BlockType.ROOT_INDEX), trailer.getDataIndexCount());
        NoOpEncodedSeeker noOpEncodedSeeker = (NoOpEncodedSeeker) encoder.encoderSeeker;
        // Assert we have read midkey metadata successfully.
        assertTrue(noOpEncodedSeeker.midLeafBlockOffset >= 0);
        assertTrue(noOpEncodedSeeker.midLeafBlockOnDiskSize > 0);
        assertTrue(noOpEncodedSeeker.midKeyEntry >= 0);
    }
}

/**
 * It's important that if you read and unpack the same HFileBlock twice, it results in an
 * identical buffer each time. Otherwise we end up with validation failures in block cache, since
 * contents may not match if the same block is cached twice. See
 * https://issues.apache.org/jira/browse/HBASE-27053
 */
@Test
public void itUnpacksIdenticallyEachTime() throws IOException {
    Path path = new Path(TEST_UTIL.getDataTestDir(), name.getMethodName());
    int totalSize = createTestBlock(path);
    // Allocate a bunch of random buffers, so we can be sure that unpack will only have "dirty"
    // buffers to choose from when allocating itself.
    Random random = new Random();
    byte[] temp = new byte[HConstants.DEFAULT_BLOCKSIZE];
    List<ByteBuff> buffs = new ArrayList<>();
    for (int i = 0; i < 10; i++) {
        ByteBuff buff = allocator.allocate(HConstants.DEFAULT_BLOCKSIZE);
        random.nextBytes(temp);
        buff.put(temp);
        buffs.add(buff);
    }
    buffs.forEach(ByteBuff::release);
    // read the same block twice. we should expect the underlying buffer below to
    // be identical each time
    HFileBlockWrapper blockOne = readBlock(path, totalSize);
    HFileBlockWrapper blockTwo = readBlock(path, totalSize);
    // first check size fields
    assertEquals(blockOne.original.getOnDiskSizeWithHeader(), blockTwo.original.getOnDiskSizeWithHeader());
    assertEquals(blockOne.original.getUncompressedSizeWithoutHeader(), blockTwo.original.getUncompressedSizeWithoutHeader());
    // next check packed buffers
    assertBuffersEqual(blockOne.original.getBufferWithoutHeader(), blockTwo.original.getBufferWithoutHeader(), blockOne.original.getOnDiskDataSizeWithHeader() - blockOne.original.headerSize());
    // now check unpacked buffers. prior to HBASE-27053, this would fail because
    // the unpacked buffer would include extra space for checksums at the end that was not written.
    // so the checksum space would be filled with random junk when re-using pooled buffers.
    assertBuffersEqual(blockOne.unpacked.getBufferWithoutHeader(), blockTwo.unpacked.getBufferWithoutHeader(), blockOne.original.getUncompressedSizeWithoutHeader());
}

/**
 * If the block on disk size is less than {@link ByteBuffAllocator}'s min allocation size, that
 * block will be allocated to heap regardless of desire for off-heap. After de-compressing the
 * block, the new size may now exceed the min allocation size. This test ensures that those
 * de-compressed blocks, which will be allocated off-heap, are properly marked as
 * {@link HFileBlock#isSharedMem()} == true See https://issues.apache.org/jira/browse/HBASE-27170
 */
@Test
public void itUsesSharedMemoryIfUnpackedBlockExceedsMinAllocationSize() throws IOException {
    Path path = new Path(TEST_UTIL.getDataTestDir(), name.getMethodName());
    int totalSize = createTestBlock(path);
    HFileBlockWrapper blockFromHFile = readBlock(path, totalSize);
    assertFalse("expected hfile block to NOT be unpacked", blockFromHFile.original.isUnpacked());
    assertFalse("expected hfile block to NOT use shared memory", blockFromHFile.original.isSharedMem());
    assertTrue("expected generated block size " + blockFromHFile.original.getOnDiskSizeWithHeader() + " to be less than " + MIN_ALLOCATION_SIZE, blockFromHFile.original.getOnDiskSizeWithHeader() < MIN_ALLOCATION_SIZE);
    assertTrue("expected generated block uncompressed size " + blockFromHFile.original.getUncompressedSizeWithoutHeader() + " to be more than " + MIN_ALLOCATION_SIZE, blockFromHFile.original.getUncompressedSizeWithoutHeader() > MIN_ALLOCATION_SIZE);
    assertTrue("expected unpacked block to be unpacked", blockFromHFile.unpacked.isUnpacked());
    assertTrue("expected unpacked block to use shared memory", blockFromHFile.unpacked.isSharedMem());
}

