    long blockSize = calculateBlockSize(maxSize, 10);
    LruAdaptiveBlockCache cache = new LruAdaptiveBlockCache(maxSize, blockSize, false, (int) Math.ceil(1.2 * maxSize / blockSize), LruAdaptiveBlockCache.DEFAULT_LOAD_FACTOR, // min
    LruAdaptiveBlockCache.DEFAULT_CONCURRENCY_LEVEL, // min
