@Test
public void testSizes() throws IOException {
    Class<?> cl;
    long expected;
    long actual;
    // KeyValue
    cl = KeyValue.class;
    expected = ClassSize.estimateBase(cl, false);
    KeyValue kv = new KeyValue();
    actual = kv.heapSize();
    if (expected != actual) {
        ClassSize.estimateBase(cl, true);
