        ClassSize.estimateBase(NonSyncTimeRangeTracker.class, true);
        ClassSize.estimateBase(CellArrayMap.class, true);
        assertEquals(expected, actual);
    }
    // Store Overhead
    cl = HStore.class;
    actual = HStore.FIXED_OVERHEAD;
    expected = ClassSize.estimateBase(cl, false);
    if (expected != actual) {
