@Test
public void testMastersSystemTimeIsUsedInMergeRegions() throws IOException {
    long regionId = EnvironmentEdgeManager.currentTime();
    TableName tableName = name.getTableName();
    RegionInfo regionInfoA = RegionInfoBuilder.newBuilder(tableName).setStartKey(HConstants.EMPTY_START_ROW).setEndKey(new byte[] { 'a' }).setSplit(false).setRegionId(regionId).setReplicaId(0).build();
    RegionInfo regionInfoB = RegionInfoBuilder.newBuilder(tableName).setStartKey(new byte[] { 'a' }).setEndKey(HConstants.EMPTY_END_ROW).setSplit(false).setRegionId(regionId).setReplicaId(0).build();
    RegionInfo mergedRegionInfo = RegionInfoBuilder.newBuilder(tableName).setStartKey(HConstants.EMPTY_START_ROW).setEndKey(HConstants.EMPTY_END_ROW).setSplit(false).setRegionId(regionId).setReplicaId(0).build();
    ServerName sn = ServerName.valueOf("bar", 0, 0);
    try (Table meta = MetaTableAccessor.getMetaHTable(UTIL.getConnection())) {
        List<RegionInfo> regionInfos = Lists.newArrayList(regionInfoA, regionInfoB);
        MetaTableAccessor.addRegionsToMeta(UTIL.getConnection(), regionInfos, 1);
        // write the serverName column with a big current time, but set the masters time as even
        // bigger. When region merge deletes the rows for regionA and regionB, the serverName columns
        // should not be seen by the following get
        long serverNameTime = EnvironmentEdgeManager.currentTime() + 100000000;
        long masterSystemTime = EnvironmentEdgeManager.currentTime() + 123456789;
        // write the serverName columns
        MetaTableAccessor.updateRegionLocation(UTIL.getConnection(), regionInfoA, sn, 1, serverNameTime);
        // assert that we have the serverName column with expected ts
        Get get = new Get(mergedRegionInfo.getRegionName());
        Result result = meta.get(get);
        Cell serverCell = result.getColumnLatestCell(HConstants.CATALOG_FAMILY, CatalogFamilyFormat.getServerColumn(0));
        assertNotNull(serverCell);
        assertEquals(serverNameTime, serverCell.getTimestamp());
        final RegionStateStore regionStateStore = UTIL.getHBaseCluster().getMaster().getAssignmentManager().getRegionStateStore();
        ManualEnvironmentEdge edge = new ManualEnvironmentEdge();
        edge.setValue(masterSystemTime);
        EnvironmentEdgeManager.injectEdge(edge);
        try {
            // now merge the regions, effectively deleting the rows for region a and b.
            regionStateStore.mergeRegions(mergedRegionInfo, new RegionInfo[] { regionInfoA, regionInfoB }, sn, TableDescriptorBuilder.newBuilder(tableName).build());
        } finally {
            EnvironmentEdgeManager.reset();
        }
        result = meta.get(get);
        serverCell = result.getColumnLatestCell(HConstants.CATALOG_FAMILY, CatalogFamilyFormat.getServerColumn(0));
        Cell startCodeCell = result.getColumnLatestCell(HConstants.CATALOG_FAMILY, CatalogFamilyFormat.getStartCodeColumn(0));
        Cell seqNumCell = result.getColumnLatestCell(HConstants.CATALOG_FAMILY, CatalogFamilyFormat.getSeqNumColumn(0));
        assertNull(serverCell);
        assertNull(startCodeCell);
        assertNull(seqNumCell);
    }
}

