    admin.mergeRegionsAsync(new byte[][] { regions.get(0).getRegionName(), regions.get(1).getRegionName() }, false).get(60, TimeUnit.SECONDS);
    admin.mergeRegionsAsync(new byte[][] { regions.get(2).getRegionName(), regions.get(3).getRegionName() }, false).get(60, TimeUnit.SECONDS);
    List<RegionInfo> mergedRegions = admin.getRegions(tn);
