@Test
public void testLocalMasterLockRecovery() throws Exception {
    ProcedureTestingUtility.setKillAndToggleBeforeStoreUpdate(procExec, true);
    CountDownLatch latch = new CountDownLatch(1);
    LockProcedure lockProc = new LockProcedure(UTIL.getConfiguration(), TableName.valueOf("table"), LockType.EXCLUSIVE, "desc", latch);
    procExec.submitProcedure(lockProc);
    assertTrue(latch.await(2000, TimeUnit.MILLISECONDS));
    // wait for proc Executor to die, then restart it and wait for Lock Procedure to get started.
    ProcedureTestingUtility.waitProcedure(procExec, lockProc.getProcId());
    assertEquals(false, procExec.isRunning());
    ProcedureTestingUtility.setKillAndToggleBeforeStoreUpdate(procExec, false);
    // remove zk lock node otherwise recovered lock will keep waiting on it.
    ProcedureTestingUtility.restart(procExec);
    while (!procExec.isStarted(lockProc.getProcId())) {
        Thread.sleep(250);
    }
    assertEquals(true, procExec.isRunning());
    ProcedureTestingUtility.waitProcedure(procExec, lockProc.getProcId());
    Procedure<?> result = procExec.getResultOrProcedure(lockProc.getProcId());
    assertTrue(result != null && !result.isFailed());
    ProcedureTestingUtility.assertProcNotFailed(procExec, lockProc.getProcId());
}

@Test
public void testMigrateStoreFileTracker() throws IOException, InterruptedException {
    // create tables to test
    for (int i = 0; i < tables.length; i++) {
        tableDescriptor = HTU.createModifyableTableDescriptor(tables[i]).setColumnFamily(ColumnFamilyDescriptorBuilder.newBuilder(fam).build()).build();
        HTU.createTable(tableDescriptor, null);
    }
    TableDescriptors tableDescriptors = HTU.getMiniHBaseCluster().getMaster().getTableDescriptors();
    for (int i = 0; i < tables.length; i++) {
        TableDescriptor tdAfterCreated = tableDescriptors.get(TableName.valueOf(tables[i]));
        // make sure that TRACKER_IMPL was set by default after tables have been created.
        Assert.assertNotNull(tdAfterCreated.getValue(StoreFileTrackerFactory.TRACKER_IMPL));
        // Remove StoreFileTracker impl from tableDescriptor
        TableDescriptor tdRemovedSFT = TableDescriptorBuilder.newBuilder(tdAfterCreated).removeValue(StoreFileTrackerFactory.TRACKER_IMPL).build();
        tableDescriptors.update(tdRemovedSFT);
    }
    HTU.getMiniHBaseCluster().stopMaster(0).join();
    HTU.getMiniHBaseCluster().startMaster();
    HTU.getMiniHBaseCluster().waitForActiveAndReadyMaster(30000);
    // wait until all tables have been migrated
    TableDescriptors tds = HTU.getMiniHBaseCluster().getMaster().getTableDescriptors();
    HTU.waitFor(30000, () -> {
        try {
            for (int i = 0; i < tables.length; i++) {
                TableDescriptor td = tds.get(TableName.valueOf(tables[i]));
                if (StringUtils.isEmpty(td.getValue(StoreFileTrackerFactory.TRACKER_IMPL))) {
                    return false;
                }
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    });
    for (String table : tables) {
        TableDescriptor td = tds.get(TableName.valueOf(table));
        assertEquals(StoreFileTrackerFactory.Trackers.DEFAULT.name(), td.getValue(StoreFileTrackerFactory.TRACKER_IMPL));
    }
}

