    assertThatEventually("executing work should see merge plan count increase", worker::getMergePlanCount, comparesEqualTo(1L));
    final long endTime = System.nanoTime();
    assertThat("rate limited normalizer should have taken at least 5 seconds", Duration.ofNanos(endTime - startTime), greaterThanOrEqualTo(Duration.ofSeconds(5)));
}

