    when(regionNormalizer.computePlansForTable(tnDescriptor)).thenReturn(Arrays.asList(new SplitNormalizationPlan(splitRegionInfo, 2), new MergeNormalizationPlan.Builder().addTarget(mergeRegionInfo1, 1).addTarget(mergeRegionInfo2, 2).build(), new SplitNormalizationPlan(splitRegionInfo, 1)));
    final Configuration conf = testingUtility.getConfiguration();
    conf.setLong(RegionNormalizerWorker.CUMULATIVE_SIZE_LIMIT_MB_KEY, 5);
    final RegionNormalizerWorker worker = new RegionNormalizerWorker(testingUtility.getConfiguration(), masterServices, regionNormalizer, queue);
