    masterRegion = UTIL.getMiniHBaseCluster().getMaster().getMasterRegion();
    try (RegionScanner scanner = masterRegion.getRegionScanner(new Scan().addFamily(HConstants.CATALOG_FAMILY))) {
        List<Cell> cells = new ArrayList<>();
