    UTIL.getMiniHBaseCluster().getMaster().getMasterRpcServices().synchronousBalanceSwitch(false);
    LOG.info("\n\nCreating tables");
    for (TableName TABLE : TABLES) {
        UTIL.createMultiRegionTable(TABLE, FAMILY, regionNum);
    }
