        return slowLogPayloadsList.size() == 8 && confirmPayloadParams(7, 3, slowLogPayloadsList) && confirmPayloadParams(0, 10, slowLogPayloadsList) && confirmPayloadParams(1, 9, slowLogPayloadsList);
    }));
