/**
 * Tests that we can trigger based on blocks scanned, and also that we properly pass the block
 * bytes scanned value through to the client.
 */
@Test
public void testLogLargeBlockBytesScanned() throws IOException {
    // Turn off slow log buffer for initial loadTable, because we were seeing core dump
    // issues coming from that slow log entry. We will re-enable below.
    HRegionServer regionServer = TEST_UTIL.getHBaseCluster().getRegionServer(0);
    regionServer.getConfiguration().setBoolean(HConstants.SLOW_LOG_BUFFER_ENABLED_KEY, false);
    regionServer.updateConfiguration();
    byte[] family = Bytes.toBytes("0");
    Table table = TEST_UTIL.createTable(TableName.valueOf("testLogLargeBlockBytesScanned"), family);
    TEST_UTIL.loadTable(table, family);
    TEST_UTIL.flush(table.getName());
    Set<ServerName> server = Collections.singleton(regionServer.getServerName());
    Admin admin = TEST_UTIL.getAdmin();
    // Turn on slow log so we capture large scan below
    regionServer.getConfiguration().setBoolean(HConstants.SLOW_LOG_BUFFER_ENABLED_KEY, true);
    regionServer.updateConfiguration();
    Scan scan = new Scan();
    scan.setCaching(1);
    try (ResultScanner scanner = table.getScanner(scan)) {
        scanner.next();
    }
    List<LogEntry> entries = admin.getLogEntries(server, "LARGE_LOG", ServerType.REGION_SERVER, 100, Collections.emptyMap());
    assertEquals(1, entries.size());
    OnlineLogRecord record = (OnlineLogRecord) entries.get(0);
    assertTrue("expected " + record.getBlockBytesScanned() + " to be >= 100", record.getBlockBytesScanned() >= 100);
    assertTrue("expected " + record.getResponseSize() + " to be < 100", record.getResponseSize() < 100);
}

@Test
public void testWALRolling() throws Exception {
    Connection connection = TEST_UTIL.getMiniHBaseCluster().getRegionServer(0).getConnection();
    waitForWALEventTrackerTable(connection);
    List<WAL> wals = TEST_UTIL.getMiniHBaseCluster().getRegionServer(0).getWALs();
    assertEquals(1, wals.size());
    AbstractFSWAL wal = (AbstractFSWAL) wals.get(0);
    Path wal1Path = wal.getOldPath();
    wal.rollWriter(true);
    FileSystem fs = TEST_UTIL.getTestFileSystem();
    long wal1Length = fs.getFileStatus(wal1Path).getLen();
    Path wal2Path = wal.getOldPath();
    String hostName = TEST_UTIL.getMiniHBaseCluster().getRegionServer(0).getServerName().getHostname();
    TEST_UTIL.waitFor(5000, () -> getTableCount(connection) >= 3);
    List<WALEventTrackerPayload> walEventsList = getRows(hostName, connection);
    // There should be atleast 2 events for wal1Name, with ROLLING and ROLLED state. Most of the
    // time we will lose ACTIVE event for the first wal creates since hmaster will take some time
    // to create hbase:waleventtracker table and by that time RS will already create the first wal
    // and will try to persist it.
    compareEvents(hostName, wal1Path.getName(), walEventsList, new ArrayList<>(Arrays.asList(WALEventTrackerListener.WalState.ROLLING.name(), WALEventTrackerListener.WalState.ROLLED.name())), false);
    // There should be only 1 event for wal2Name which is current wal, with ACTIVE state
    compareEvents(hostName, wal2Path.getName(), walEventsList, new ArrayList<>(Arrays.asList(WALEventTrackerListener.WalState.ACTIVE.name())), true);
    // Check that event with wal1Path and state ROLLED has the wal length set.
    checkWALRolledEventHasSize(walEventsList, wal1Path.getName(), wal1Length);
}

/*
   * Test whether wal event tracker metrics are being incremented.
   */
@Test
public void testMetrics() throws Exception {
    String rsName = "test-region-server";
    String walName = "test-wal-0";
    long timeStamp = EnvironmentEdgeManager.currentTime();
    String walState = WALEventTrackerListener.WalState.ACTIVE.name();
    long walLength = 100L;
    WALEventTrackerPayload payload = new WALEventTrackerPayload(rsName, walName, timeStamp, walState, walLength);
    Configuration conf = HBaseConfiguration.create();
    conf.setBoolean(WAL_EVENT_TRACKER_ENABLED_KEY, true);
    conf.setLong(WALEventTrackerTableAccessor.SLEEP_INTERVAL_KEY, 100);
    MetricsWALEventTrackerSourceImpl source = new MetricsWALEventTrackerSourceImpl(name.getMethodName(), name.getMethodName(), name.getMethodName(), name.getMethodName());
    WALEventTrackerQueueService service = new WALEventTrackerQueueService(conf, source);
    service.addToQueue(payload);
    Connection mockConnection = mock(Connection.class);
    doReturn(conf).when(mockConnection).getConfiguration();
    // Always throw IOException whenever mock connection is being used.
    doThrow(new IOException()).when(mockConnection).getTable(WAL_EVENT_TRACKER_TABLE_NAME);
    assertEquals(0L, source.getFailedPuts());
    assertEquals(0L, source.getNumRecordsFailedPuts());
    // Persist all the events.
    service.persistAll(mockConnection);
    assertEquals(1L, source.getFailedPuts());
    assertEquals(1L, source.getNumRecordsFailedPuts());
    // Verify that we tried MAX_RETRY_ATTEMPTS retry attempts to persist.
    verify(mockConnection, times(1 + WALEventTrackerTableAccessor.DEFAULT_MAX_ATTEMPTS)).getTable(WAL_EVENT_TRACKER_TABLE_NAME);
}

