    assertEquals(SpaceViolationPolicy.NO_INSERTS, snapshot.getQuotaStatus().getPolicy().get());
}

@Test
public void testQuotaStatusFromMaster() throws Exception {
    // 25KB
    final long sizeLimit = 1024L * 25L;
    // As of 2.0.0-beta-2, this 1KB of "Cells" actually results in about 15KB on disk (HFiles)
    // This is skewed a bit since we're writing such little data, so the test needs to keep
    // this in mind; else, the quota will be in violation before the test expects it to be.
    // 1KB
    final long tableSize = 1024L * 1;
    final long nsLimit = Long.MAX_VALUE;
    final int numRegions = 10;
    final TableName tn = helper.createTableWithRegions(numRegions);
    // Define the quota
    QuotaSettings settings = QuotaSettingsFactory.limitTableSpace(tn, sizeLimit, SpaceViolationPolicy.NO_INSERTS);
    TEST_UTIL.getAdmin().setQuota(settings);
    QuotaSettings nsSettings = QuotaSettingsFactory.limitNamespaceSpace(tn.getNamespaceAsString(), nsLimit, SpaceViolationPolicy.NO_INSERTS);
    TEST_UTIL.getAdmin().setQuota(nsSettings);
    // Write at least `tableSize` data
    helper.writeData(tn, tableSize);
    final Connection conn = TEST_UTIL.getConnection();
    // Make sure the master has a snapshot for our table
    Waiter.waitFor(TEST_UTIL.getConfiguration(), 30 * 1000, new Predicate<Exception>() {

        @Override
        public boolean evaluate() throws Exception {
            SpaceQuotaSnapshot snapshot = (SpaceQuotaSnapshot) conn.getAdmin().getCurrentSpaceQuotaSnapshot(tn);
            LOG.info("Table snapshot after initial ingest: " + snapshot);
            if (snapshot == null) {
                return false;
            }
            return snapshot.getLimit() == sizeLimit && snapshot.getUsage() > 0L;
        }
    });
    final AtomicReference<Long> nsUsage = new AtomicReference<>();
    // If we saw the table snapshot, we should also see the namespace snapshot
    Waiter.waitFor(TEST_UTIL.getConfiguration(), 30 * 1000 * 1000, new Predicate<Exception>() {

        @Override
        public boolean evaluate() throws Exception {
            SpaceQuotaSnapshot snapshot = (SpaceQuotaSnapshot) conn.getAdmin().getCurrentSpaceQuotaSnapshot(tn.getNamespaceAsString());
            LOG.debug("Namespace snapshot after initial ingest: " + snapshot);
            if (snapshot == null) {
                return false;
            }
            nsUsage.set(snapshot.getUsage());
            return snapshot.getLimit() == nsLimit && snapshot.getUsage() > 0;
        }
    });
    // Sanity check: the below assertions will fail if we somehow write too much data
    // and force the table to move into violation before we write the second bit of data.
    SpaceQuotaSnapshot snapshot = (SpaceQuotaSnapshot) conn.getAdmin().getCurrentSpaceQuotaSnapshot(tn);
    assertTrue("QuotaSnapshot for " + tn + " should be non-null and not in violation", snapshot != null && !snapshot.getQuotaStatus().isInViolation());
    try {
        helper.writeData(tn, tableSize * 2L);
    } catch (RetriesExhaustedWithDetailsException | SpaceLimitingException e) {
        // Pass
    }
    // Wait for the status to move to violation
    Waiter.waitFor(TEST_UTIL.getConfiguration(), 30 * 1000, new Predicate<Exception>() {

        @Override
        public boolean evaluate() throws Exception {
            SpaceQuotaSnapshot snapshot = (SpaceQuotaSnapshot) conn.getAdmin().getCurrentSpaceQuotaSnapshot(tn);
            LOG.info("Table snapshot after second ingest: " + snapshot);
            if (snapshot == null) {
                return false;
            }
            return snapshot.getQuotaStatus().isInViolation();
        }
    });
    // The namespace should still not be in violation, but have a larger usage than previously
    Waiter.waitFor(TEST_UTIL.getConfiguration(), 30 * 1000, new Predicate<Exception>() {

        @Override
        public boolean evaluate() throws Exception {
            SpaceQuotaSnapshot snapshot = (SpaceQuotaSnapshot) conn.getAdmin().getCurrentSpaceQuotaSnapshot(tn.getNamespaceAsString());
            LOG.debug("Namespace snapshot after second ingest: " + snapshot);
            if (snapshot == null) {
                return false;
            }
            return snapshot.getUsage() > nsUsage.get() && !snapshot.getQuotaStatus().isInViolation();
        }
    });
}

@Test
public void testDeleteSnapshots() throws Exception {
    TableName tn = TableName.valueOf(name.getMethodName());
    try (Table t = connection.getTable(QuotaTableUtil.QUOTA_TABLE_NAME)) {
        Quotas quota = Quotas.newBuilder().setSpace(QuotaProtos.SpaceQuota.newBuilder().setSoftLimit(7L).setViolationPolicy(QuotaProtos.SpaceViolationPolicy.NO_WRITES).build()).build();
        QuotaUtil.addTableQuota(connection, tn, quota);
        String snapshotName = name.getMethodName() + "_snapshot";
        t.put(QuotaTableUtil.createPutForSnapshotSize(tn, snapshotName, 3L));
        t.put(QuotaTableUtil.createPutForSnapshotSize(tn, snapshotName, 5L));
        assertEquals(1, QuotaTableUtil.getObservedSnapshotSizes(connection).size());
        List<Delete> deletes = QuotaTableUtil.createDeletesForExistingTableSnapshotSizes(connection);
        assertEquals(1, deletes.size());
        t.delete(deletes);
        assertEquals(0, QuotaTableUtil.getObservedSnapshotSizes(connection).size());
        String ns = name.getMethodName();
        t.put(QuotaTableUtil.createPutForNamespaceSnapshotSize(ns, 5L));
        t.put(QuotaTableUtil.createPutForNamespaceSnapshotSize(ns, 3L));
        assertEquals(3L, QuotaTableUtil.getNamespaceSnapshotSize(connection, ns));
        deletes = QuotaTableUtil.createDeletesForExistingNamespaceSnapshotSizes(connection);
        assertEquals(1, deletes.size());
        t.delete(deletes);
        assertEquals(0L, QuotaTableUtil.getNamespaceSnapshotSize(connection, ns));
        t.put(QuotaTableUtil.createPutForSnapshotSize(TableName.valueOf("t1"), "s1", 3L));
        t.put(QuotaTableUtil.createPutForSnapshotSize(TableName.valueOf("t2"), "s2", 3L));
        t.put(QuotaTableUtil.createPutForSnapshotSize(TableName.valueOf("t3"), "s3", 3L));
        t.put(QuotaTableUtil.createPutForSnapshotSize(TableName.valueOf("t4"), "s4", 3L));
        t.put(QuotaTableUtil.createPutForSnapshotSize(TableName.valueOf("t1"), "s5", 3L));
        t.put(QuotaTableUtil.createPutForNamespaceSnapshotSize("ns1", 3L));
        t.put(QuotaTableUtil.createPutForNamespaceSnapshotSize("ns2", 3L));
        t.put(QuotaTableUtil.createPutForNamespaceSnapshotSize("ns3", 3L));
        assertEquals(5, QuotaTableUtil.getTableSnapshots(connection).size());
        assertEquals(3, QuotaTableUtil.getNamespaceSnapshots(connection).size());
        Multimap<TableName, String> tableSnapshotEntriesToRemove = HashMultimap.create();
        tableSnapshotEntriesToRemove.put(TableName.valueOf("t1"), "s1");
        tableSnapshotEntriesToRemove.put(TableName.valueOf("t3"), "s3");
        tableSnapshotEntriesToRemove.put(TableName.valueOf("t4"), "s4");
        Set<String> namespaceSnapshotEntriesToRemove = new HashSet<>();
        namespaceSnapshotEntriesToRemove.add("ns2");
        namespaceSnapshotEntriesToRemove.add("ns1");
        deletes = QuotaTableUtil.createDeletesForExistingTableSnapshotSizes(tableSnapshotEntriesToRemove);
        assertEquals(3, deletes.size());
        deletes = QuotaTableUtil.createDeletesForExistingNamespaceSnapshotSizes(namespaceSnapshotEntriesToRemove);
        assertEquals(2, deletes.size());
    }
}

