    admin.setQuota(QuotaSettingsFactory.throttleNamespace(NAMESPACE, ThrottleType.REQUEST_NUMBER, 13, TimeUnit.MINUTES));
    triggerNamespaceCacheRefresh(TEST_UTIL, false, TABLE_NAMES[1]);
