@Test
public void testExceedThrottleQuota() throws Exception {
    final Admin admin = TEST_UTIL.getAdmin();
    admin.setQuota(QuotaSettingsFactory.throttleTable(TABLE_NAMES[0], ThrottleType.WRITE_NUMBER, 5, TimeUnit.MINUTES));
    triggerTableCacheRefresh(TEST_UTIL, false, TABLE_NAMES[0]);
    admin.setQuota(QuotaSettingsFactory.throttleRegionServer(QuotaTableUtil.QUOTA_REGION_SERVER_ROW_KEY, ThrottleType.WRITE_NUMBER, 20, TimeUnit.SECONDS));
    admin.setQuota(QuotaSettingsFactory.throttleRegionServer(QuotaTableUtil.QUOTA_REGION_SERVER_ROW_KEY, ThrottleType.READ_NUMBER, 10, TimeUnit.SECONDS));
    triggerRegionServerCacheRefresh(TEST_UTIL, false);
    // enable exceed throttle quota
    admin.exceedThrottleQuotaSwitch(true);
    // exceed table limit and allowed by region server limit
    triggerExceedThrottleQuotaCacheRefresh(TEST_UTIL, true);
    waitMinuteQuota();
    assertEquals(10, doPuts(10, FAMILY, QUALIFIER, tables[0]));
    // exceed table limit and throttled by region server limit
    waitMinuteQuota();
    assertEquals(20, doPuts(25, FAMILY, QUALIFIER, tables[0]));
    // set region server limiter is lower than table limiter
    admin.setQuota(QuotaSettingsFactory.throttleRegionServer(QuotaTableUtil.QUOTA_REGION_SERVER_ROW_KEY, ThrottleType.WRITE_NUMBER, 2, TimeUnit.SECONDS));
    triggerRegionServerCacheRefresh(TEST_UTIL, false);
    // throttled by region server limiter
    waitMinuteQuota();
    assertEquals(2, doPuts(10, FAMILY, QUALIFIER, tables[0]));
    admin.setQuota(QuotaSettingsFactory.throttleRegionServer(QuotaTableUtil.QUOTA_REGION_SERVER_ROW_KEY, ThrottleType.WRITE_NUMBER, 20, TimeUnit.SECONDS));
    triggerRegionServerCacheRefresh(TEST_UTIL, false);
    // disable exceed throttle quota
    admin.exceedThrottleQuotaSwitch(false);
    triggerExceedThrottleQuotaCacheRefresh(TEST_UTIL, false);
    waitMinuteQuota();
    // throttled by table limit
    assertEquals(5, doPuts(10, FAMILY, QUALIFIER, tables[0]));
    // enable exceed throttle quota and unthrottle region server
    admin.exceedThrottleQuotaSwitch(true);
    triggerExceedThrottleQuotaCacheRefresh(TEST_UTIL, true);
    waitMinuteQuota();
    admin.setQuota(QuotaSettingsFactory.unthrottleRegionServer(QuotaTableUtil.QUOTA_REGION_SERVER_ROW_KEY));
    triggerRegionServerCacheRefresh(TEST_UTIL, true);
    waitMinuteQuota();
    // throttled by table limit
    assertEquals(5, doPuts(10, FAMILY, QUALIFIER, tables[0]));
    // disable exceed throttle quota
    admin.exceedThrottleQuotaSwitch(false);
    triggerExceedThrottleQuotaCacheRefresh(TEST_UTIL, false);
    // unthrottle table
    admin.setQuota(QuotaSettingsFactory.unthrottleTable(TABLE_NAMES[0]));
    triggerTableCacheRefresh(TEST_UTIL, true, TABLE_NAMES[0]);
}

@Test
public void testUserGlobalThrottleWithCustomOverride() throws Exception {
    final Admin admin = TEST_UTIL.getAdmin();
    final String userOverrideWithQuota = User.getCurrent().getShortName() + "123";
    // Add 6req/min limit
    admin.setQuota(QuotaSettingsFactory.throttleUser(userOverrideWithQuota, ThrottleType.REQUEST_NUMBER, 6, TimeUnit.MINUTES));
    Table tableWithThrottle = TEST_UTIL.getConnection().getTableBuilder(TABLE_NAME, null).setRequestAttribute(CUSTOM_OVERRIDE_KEY, Bytes.toBytes(userOverrideWithQuota)).build();
    Table tableWithoutThrottle = TEST_UTIL.getConnection().getTableBuilder(TABLE_NAME, null).setRequestAttribute(QuotaCache.QUOTA_USER_REQUEST_ATTRIBUTE_OVERRIDE_KEY, Bytes.toBytes(userOverrideWithQuota)).build();
    Table tableWithoutThrottle2 = TEST_UTIL.getConnection().getTableBuilder(TABLE_NAME, null).build();
    // warm things up
    doPuts(10, FAMILY, QUALIFIER, tableWithThrottle);
    doPuts(10, FAMILY, QUALIFIER, tableWithoutThrottle);
    doPuts(10, FAMILY, QUALIFIER, tableWithoutThrottle2);
    // should reject some requests
    assertTrue(10 > doPuts(10, FAMILY, QUALIFIER, tableWithThrottle));
    // should accept all puts
    assertEquals(10, doPuts(10, FAMILY, QUALIFIER, tableWithoutThrottle));
    // should accept all puts
    assertEquals(10, doPuts(10, FAMILY, QUALIFIER, tableWithoutThrottle2));
    // Remove all the limits
    admin.setQuota(QuotaSettingsFactory.unthrottleUser(userOverrideWithQuota));
    Thread.sleep(60_000);
    assertEquals(10, doPuts(10, FAMILY, QUALIFIER, tableWithThrottle));
    assertEquals(10, doPuts(10, FAMILY, QUALIFIER, tableWithoutThrottle));
    assertEquals(10, doPuts(10, FAMILY, QUALIFIER, tableWithoutThrottle2));
}

