/**
 * Here is the unit test for UserScanQueryMatcher#mergeFilterResponse, when the number of cells
 * exceed the versions requested in scan, we should return SEEK_NEXT_COL, but if current match
 * code is INCLUDE_AND_SEEK_NEXT_ROW, we can optimize to choose the max step between SEEK_NEXT_COL
 * and INCLUDE_AND_SEEK_NEXT_ROW, which is SEEK_NEXT_ROW. <br/>
 */
@Test
public void testMergeFilterResponseCase1() throws IOException {
    List<MatchCode> expected = new ArrayList<>();
    expected.add(MatchCode.INCLUDE);
    expected.add(MatchCode.INCLUDE);
    expected.add(MatchCode.SEEK_NEXT_ROW);
    Scan scanWithFilter = new Scan(scan).setFilter(new AlwaysIncludeFilter()).readVersions(2);
    long now = EnvironmentEdgeManager.currentTime();
    // scan with column 2,4,5, the family with maxVersion = 3
    UserScanQueryMatcher qm = UserScanQueryMatcher.create(scanWithFilter, new ScanInfo(this.conf, fam2, 0, 3, ttl, KeepDeletedCells.FALSE, HConstants.DEFAULT_BLOCKSIZE, 0, rowComparator, false), get.getFamilyMap().get(fam2), now - ttl, now, null);
    List<KeyValue> memstore = new ArrayList<>();
    // match code will be INCLUDE
    memstore.add(new KeyValue(row1, fam1, col5, 1, data));
    // match code will be INCLUDE
    memstore.add(new KeyValue(row1, fam1, col5, 2, data));
    // match code will be SEEK_NEXT_ROW , which is max(INCLUDE_AND_SEEK_NEXT_ROW, SEEK_NEXT_COL).
    memstore.add(new KeyValue(row1, fam1, col5, 3, data));
    KeyValue k = memstore.get(0);
    qm.setToNewRow(k);
    for (int i = 0; i < memstore.size(); i++) {
        assertEquals(expected.get(i), qm.match(memstore.get(i)));
    }
    scanWithFilter = new Scan(scan).setFilter(new AlwaysIncludeFilter()).readVersions(1);
    qm = UserScanQueryMatcher.create(scanWithFilter, new ScanInfo(this.conf, fam2, 0, 2, ttl, KeepDeletedCells.FALSE, HConstants.DEFAULT_BLOCKSIZE, 0, rowComparator, false), get.getFamilyMap().get(fam2), now - ttl, now, null);
    List<KeyValue> memstore2 = new ArrayList<>();
    // match code will be INCLUDE
    memstore2.add(new KeyValue(row2, fam1, col2, 1, data));
    // match code will be SEEK_NEXT_COL, which is max(INCLUDE_AND_SEEK_NEXT_COL, SEEK_NEXT_COL).
    memstore2.add(new KeyValue(row2, fam1, col2, 2, data));
    k = memstore2.get(0);
    qm.setToNewRow(k);
    assertEquals(MatchCode.INCLUDE, qm.match(memstore2.get(0)));
    assertEquals(MatchCode.SEEK_NEXT_COL, qm.match(memstore2.get(1)));
}

/**
 * Here is the unit test for UserScanQueryMatcher#mergeFilterResponse: the match code may be
 * changed to SEEK_NEXT_COL or INCLUDE_AND_SEEK_NEXT_COL after merging with filterResponse, even
 * if the passed match code is neither SEEK_NEXT_COL nor INCLUDE_AND_SEEK_NEXT_COL. In that case,
 * we need to make sure that the ColumnTracker has been switched to the next column. <br/>
 * An effective test way is: we only need to check the cell from getKeyForNextColumn(). because
 * that as long as the UserScanQueryMatcher returns SEEK_NEXT_COL or INCLUDE_AND_SEEK_NEXT_COL,
 * UserScanQueryMatcher#getKeyForNextColumn should return an cell whose column is larger than the
 * current cell's.
 */
@Test
public void testMergeFilterResponseCase2() throws Exception {
    List<MatchCode> expected = new ArrayList<>();
    expected.add(ScanQueryMatcher.MatchCode.INCLUDE);
    expected.add(ScanQueryMatcher.MatchCode.INCLUDE);
    expected.add(ScanQueryMatcher.MatchCode.INCLUDE);
    expected.add(ScanQueryMatcher.MatchCode.SEEK_NEXT_COL);
    Scan scanWithFilter = new Scan(scan).setFilter(new AlwaysIncludeFilter()).readVersions(3);
    long now = EnvironmentEdgeManager.currentTime();
    // scan with column 2,4,5, the family with maxVersion = 5
    UserScanQueryMatcher qm = UserScanQueryMatcher.create(scanWithFilter, new ScanInfo(this.conf, fam2, 0, 5, ttl, KeepDeletedCells.FALSE, HConstants.DEFAULT_BLOCKSIZE, 0, rowComparator, false), get.getFamilyMap().get(fam2), now - ttl, now, null);
    List<KeyValue> memstore = new ArrayList<>();
    // match code will be INCLUDE
    memstore.add(new KeyValue(row1, fam1, col2, 1, data));
    // match code will be INCLUDE
    memstore.add(new KeyValue(row1, fam1, col2, 2, data));
    // match code will be INCLUDE
    memstore.add(new KeyValue(row1, fam1, col2, 3, data));
    // match code will be SEEK_NEXT_COL
    memstore.add(new KeyValue(row1, fam1, col2, 4, data));
    KeyValue k = memstore.get(0);
    qm.setToNewRow(k);
    for (int i = 0; i < memstore.size(); i++) {
        assertEquals(expected.get(i), qm.match(memstore.get(i)));
    }
    // For last cell, the query matcher will return SEEK_NEXT_COL, and the
    // ColumnTracker will skip to the next column, which is col4.
    Cell lastCell = memstore.get(memstore.size() - 1);
    Cell nextCell = qm.getKeyForNextColumn(lastCell);
    assertArrayEquals(nextCell.getQualifierArray(), col4);
}

@Test
public void testScheduleFlush() throws IOException, InterruptedException {
    conf.setLong(RegionReplicationBufferManager.MAX_PENDING_SIZE, 1024 * 1024);
    manager = new RegionReplicationBufferManager(rsServices);
    RegionInfo info1 = RegionInfoBuilder.newBuilder(TableName.valueOf("info1")).build();
    RegionInfo info2 = RegionInfoBuilder.newBuilder(TableName.valueOf("info2")).build();
    HRegion region1 = mockRegion(info1, 1000);
    HRegion region2 = mockRegion(info2, 10000);
    when(rsServices.getRegions()).thenReturn(Arrays.asList(region1, region2));
    CountDownLatch arrive = new CountDownLatch(1);
    CountDownLatch resume = new CountDownLatch(1);
    when(region2.flushcache(anyBoolean(), anyBoolean(), any())).then(i -> {
        arrive.countDown();
        resume.await();
        FlushResultImpl result = mock(FlushResultImpl.class);
        when(result.isFlushSucceeded()).thenReturn(true);
        return result;
    });
    // hit the soft limit, should trigger a flush
    assertTrue(manager.increase(1000 * 1024));
    arrive.await();
    // we should have called getRegions once to find the region to flush
    verify(rsServices, times(1)).getRegions();
    // hit the hard limit, but since the background thread is running as we haven't call the
    // resume.countDown yet, the schedule of the new background flush task should be discard
    // silently.
    assertFalse(manager.increase(100 * 1024));
    resume.countDown();
    // wait several seconds and then check the getRegions call, we should not call it second time
    Thread.sleep(2000);
    verify(rsServices, times(1)).getRegions();
}

@Test
public void testRequest() throws InterruptedException {
    // should call request directly
    flushRequester.requestFlush(100L);
    verify(requester, times(1)).run();
    // should not call request directly, since the min interval is 1 second
    flushRequester.requestFlush(200L);
    verify(requester, times(1)).run();
    Thread.sleep(2000);
    verify(requester, times(2)).run();
    // should call request directly because we have already elapsed more than 1 second
    Thread.sleep(2000);
    flushRequester.requestFlush(300L);
    verify(requester, times(3)).run();
}

