public void testInvalidColumnFamily() throws IOException, InterruptedException {
    final TableName tableName = TableName.valueOf(name.getMethodName());
    byte[] family = Bytes.toBytes("family");
    byte[] fakecf = Bytes.toBytes("fakecf");
    boolean caughtMinorCompact = false;
    boolean caughtMajorCompact = false;
    Table ht = null;
    try {
        ht = TEST_UTIL.createTable(tableName, family);
        Admin admin = TEST_UTIL.getAdmin();
        try {
            admin.compact(tableName, fakecf);
        } catch (IOException ioe) {
            caughtMinorCompact = true;
        }
        try {
            admin.majorCompact(tableName, fakecf);
        } catch (IOException ioe) {
            caughtMajorCompact = true;
        }
    } finally {
        if (ht != null) {
            TEST_UTIL.deleteTable(tableName);
        }
        assertTrue(caughtMinorCompact);
        assertTrue(caughtMajorCompact);
    }
}

@Test
public void testCompaction() throws Exception {
    TableName table = TableName.valueOf("t1");
    admin.compactionSwitch(false, new ArrayList<>(0));
    try (Table t = createTable(TEST_UTIL, table)) {
        for (int i = 0; i < 2; i++) {
            put(t);
            admin.flush(table);
        }
        admin.compactionSwitch(true, new ArrayList<>(0));
        admin.majorCompact(table);
        List<JVMClusterUtil.RegionServerThread> regionServerThreads = TEST_UTIL.getHBaseCluster().getRegionServerThreads();
        TEST_UTIL.waitFor(2 * 60 * 1000L, () -> {
            boolean result = true;
            for (JVMClusterUtil.RegionServerThread regionServerThread : regionServerThreads) {
                HRegionServer regionServer = regionServerThread.getRegionServer();
                List<HRegion> regions = regionServer.getRegions(table);
                for (HRegion region : regions) {
                    List<String> storeFileList = region.getStoreFileList(new byte[][] { COLUMN });
                    if (storeFileList.size() > 1) {
                        result = false;
                    }
                }
            }
            return result;
        });
    }
}

