        assertTrue(Bytes.equals(T11, r.getRow()));
    } finally {
        if (region != null) {
            try {
                WAL wal = region.getWAL();
                region.close();
                wal.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}

