    final long originalSize = originalCell.getSerializedSize();
    Cell addCell = ExtendedCellBuilderFactory.create(CellBuilderType.DEEP_COPY).setRow(row).setFamily(COLUMN_FAMILY_BYTES).setQualifier(qual1).setTimestamp(EnvironmentEdgeManager.currentTime()).setType(KeyValue.Type.Put.getCode()).setValue(Bytes.toBytes("xxxxxxxxxx")).build();
    final long addSize = addCell.getSerializedSize();
