@Test
public void testRegionReplicaSecondary() throws IOException {
    // create a primary region, load some data and flush
    // create a secondary region, and do a get against that
    Path rootDir = new Path(dir + name.getMethodName());
    CommonFSUtils.setRootDir(TEST_UTIL.getConfiguration(), rootDir);
    byte[][] families = new byte[][] { Bytes.toBytes("cf1"), Bytes.toBytes("cf2"), Bytes.toBytes("cf3") };
    byte[] cq = Bytes.toBytes("cq");
    TableDescriptorBuilder builder = TableDescriptorBuilder.newBuilder(TableName.valueOf(name.getMethodName()));
    for (byte[] family : families) {
        builder.setColumnFamily(ColumnFamilyDescriptorBuilder.of(family));
    }
    TableDescriptor tableDescriptor = builder.build();
    long time = EnvironmentEdgeManager.currentTime();
    RegionInfo primaryHri = RegionInfoBuilder.newBuilder(tableDescriptor.getTableName()).setRegionId(time).setReplicaId(0).build();
    RegionInfo secondaryHri = RegionInfoBuilder.newBuilder(tableDescriptor.getTableName()).setRegionId(time).setReplicaId(1).build();
    HRegion primaryRegion = null, secondaryRegion = null;
    try {
        primaryRegion = HBaseTestingUtil.createRegionAndWAL(primaryHri, rootDir, TEST_UTIL.getConfiguration(), tableDescriptor);
        // load some data
        putData(primaryRegion, 0, 1000, cq, families);
        // flush region
        primaryRegion.flush(true);
        // open secondary region
        secondaryRegion = HRegion.openHRegion(rootDir, secondaryHri, tableDescriptor, null, CONF);
        verifyData(secondaryRegion, 0, 1000, cq, families);
    } finally {
        if (primaryRegion != null) {
            HBaseTestingUtil.closeRegionAndWAL(primaryRegion);
        }
        if (secondaryRegion != null) {
            HBaseTestingUtil.closeRegionAndWAL(secondaryRegion);
        }
    }
}

