    this.store.add(kv, null);
    flush(3);
    ExecutorService service = Executors.newFixedThreadPool(2);
    Scan scan = new Scan(new Get(row));
    Future<KeyValueScanner> scanFuture = service.submit(() -> {
        try {
            LOG.info(">>>> creating scanner");
            return this.store.createScanner(scan, new ScanInfo(HBaseConfiguration.create(), ColumnFamilyDescriptorBuilder.newBuilder(family).setMaxVersions(4).build(), Long.MAX_VALUE, 0, CellComparator.getInstance()), scan.getFamilyMap().get(store.getColumnFamilyDescriptor().getName()), 0);
        } catch (IOException e) {
            e.printStackTrace();
