    // a put into another store (CF) should have no effect
    p = new Put(T1, ts - 10);
    p.addColumn(c1, c0, T1);
    region.put(p);
    // all the following deletes affect the put
    Delete d = new Delete(T1, ts);
    d.addColumns(c0, c0, ts);
    region.delete(d);
    d = new Delete(T1, ts);
    d.addFamily(c0, ts);
