    d.addColumns(c0, c0, ts);
    region.delete(d);
    d = new Delete(T1, ts);
    d.addFamily(c0, ts);
    region.delete(d);
    d = new Delete(T1, ts);
    d.addColumn(c0, c0, ts + 1);
    region.delete(d);
    d = new Delete(T1, ts);
    d.addColumn(c0, c0, ts + 2);
