@Test
public void testParallelism() throws Exception {
    final MultiVersionConcurrencyControl mvcc = new MultiVersionConcurrencyControl();
    final AtomicBoolean finished = new AtomicBoolean(false);
    // fail flag for the reader thread
    final AtomicBoolean readerFailed = new AtomicBoolean(false);
    final AtomicLong failedAt = new AtomicLong();
    Runnable reader = new Runnable() {

        @Override
        public void run() {
            long prev = mvcc.getReadPoint();
            while (!finished.get()) {
                long newPrev = mvcc.getReadPoint();
                if (newPrev < prev) {
                    // serious problem.
                    System.out.println("Reader got out of order, prev: " + prev + " next was: " + newPrev);
                    readerFailed.set(true);
                    // might as well give up
                    failedAt.set(newPrev);
                    return;
                }
            }
        }
    };
    // writer thread parallelism.
    int n = 20;
    Thread[] writers = new Thread[n];
    AtomicBoolean[] statuses = new AtomicBoolean[n];
    Thread readThread = new Thread(reader);
    for (int i = 0; i < n; ++i) {
        statuses[i] = new AtomicBoolean(true);
        writers[i] = new Thread(new Writer(finished, mvcc, statuses[i]));
        writers[i].start();
    }
    readThread.start();
    try {
        Thread.sleep(10 * 1000);
    } catch (InterruptedException ex) {
    }
    finished.set(true);
    readThread.join();
    for (int i = 0; i < n; ++i) {
        writers[i].join();
    }
    // check failure.
    Assert.assertFalse(readerFailed.get());
    for (int i = 0; i < n; ++i) {
        Assert.assertTrue(statuses[i].get());
    }
}

@Test
public void testSimpleMvccOps() {
    MultiVersionConcurrencyControl mvcc = new MultiVersionConcurrencyControl();
    long readPoint = mvcc.getReadPoint();
    MultiVersionConcurrencyControl.WriteEntry writeEntry = mvcc.begin();
    mvcc.completeAndWait(writeEntry);
    assertEquals(readPoint + 1, mvcc.getReadPoint());
    writeEntry = mvcc.begin();
    // The write point advances even though we may have 'failed'... call complete on fail.
    mvcc.complete(writeEntry);
    assertEquals(readPoint + 2, mvcc.getWritePoint());
}

@Test
public void MutateRowsAndCheckPostKill() throws IOException, InterruptedException {
    final TableName tableName = TableName.valueOf("test");
    Admin admin = null;
    Table hTable = null;
    try {
        admin = connection.getAdmin();
        hTable = connection.getTable(tableName);
        TableDescriptor tableDescriptor = TableDescriptorBuilder.newBuilder(tableName).setColumnFamily(ColumnFamilyDescriptorBuilder.of(fam1)).build();
        admin.createTable(tableDescriptor);
        // Add a multi
        RowMutations rm = new RowMutations(row1);
        Put p1 = new Put(row1);
        p1.addColumn(fam1, qual1, value1);
        p1.setDurability(Durability.SYNC_WAL);
        rm.add(p1);
        hTable.mutateRow(rm);
        // Add a put
        Put p2 = new Put(row1);
        p2.addColumn(fam1, qual2, value2);
        p2.setDurability(Durability.SYNC_WAL);
        hTable.put(p2);
        HRegionServer rs1 = TESTING_UTIL.getRSForFirstRegionInTable(tableName);
        long now = EnvironmentEdgeManager.currentTime();
        // Send the RS Load to ensure correct lastflushedseqid for stores
        rs1.tryRegionServerReport(now - 30000, now);
        // Kill the RS to trigger wal replay
        cluster.killRegionServer(rs1.getServerName());
        // Ensure correct data exists
        Get g1 = new Get(row1);
        Result result = hTable.get(g1);
        assertTrue(result.getValue(fam1, qual1) != null);
        assertEquals(0, Bytes.compareTo(result.getValue(fam1, qual1), value1));
        assertTrue(result.getValue(fam1, qual2) != null);
        assertEquals(0, Bytes.compareTo(result.getValue(fam1, qual2), value2));
    } finally {
        if (admin != null) {
            admin.close();
        }
        if (hTable != null) {
            hTable.close();
        }
    }
}

