@Test
public void testCleanMergeReference() throws Exception {
    LOG.info("Starting " + name.getMethodName());
    ADMIN.catalogJanitorSwitch(false);
    final TableName tableName = TableName.valueOf(name.getMethodName());
    try {
        // Create table and load data.
        Table table = createTableAndLoadData(MASTER, tableName);
        // Merge 1st and 2nd region
        mergeRegionsAndVerifyRegionNum(MASTER, tableName, 0, 1, INITIAL_REGION_NUM - 1);
        verifyRowCount(table, ROWSIZE);
        table.close();
        List<Pair<RegionInfo, ServerName>> tableRegions = MetaTableAccessor.getTableRegionsAndLocations(MASTER.getConnection(), tableName);
        RegionInfo mergedRegionInfo = tableRegions.get(0).getFirst();
        TableDescriptor tableDescriptor = MASTER.getTableDescriptors().get(tableName);
        Result mergedRegionResult = MetaTableAccessor.getRegionResult(MASTER.getConnection(), mergedRegionInfo);
        // contains merge reference in META
        assertTrue(CatalogFamilyFormat.hasMergeRegions(mergedRegionResult.rawCells()));
        // merging regions' directory are in the file system all the same
        List<RegionInfo> p = CatalogFamilyFormat.getMergeRegions(mergedRegionResult.rawCells());
        RegionInfo regionA = p.get(0);
        RegionInfo regionB = p.get(1);
        FileSystem fs = MASTER.getMasterFileSystem().getFileSystem();
        Path rootDir = MASTER.getMasterFileSystem().getRootDir();
        Path tabledir = CommonFSUtils.getTableDir(rootDir, mergedRegionInfo.getTable());
        Path regionAdir = new Path(tabledir, regionA.getEncodedName());
        Path regionBdir = new Path(tabledir, regionB.getEncodedName());
        assertTrue(fs.exists(regionAdir));
        assertTrue(fs.exists(regionBdir));
        ColumnFamilyDescriptor[] columnFamilies = tableDescriptor.getColumnFamilies();
        HRegionFileSystem hrfs = new HRegionFileSystem(TEST_UTIL.getConfiguration(), fs, tabledir, mergedRegionInfo);
        int count = 0;
        for (ColumnFamilyDescriptor colFamily : columnFamilies) {
            count += hrfs.getStoreFiles(colFamily.getNameAsString()).size();
        }
        ADMIN.compactRegion(mergedRegionInfo.getRegionName());
        // clean up the merged region store files
        // wait until merged region have reference file
        long timeout = EnvironmentEdgeManager.currentTime() + waitTime;
        int newcount = 0;
        while (EnvironmentEdgeManager.currentTime() < timeout) {
            for (ColumnFamilyDescriptor colFamily : columnFamilies) {
                newcount += hrfs.getStoreFiles(colFamily.getNameAsString()).size();
            }
            if (newcount > count) {
                break;
            }
            Thread.sleep(50);
        }
        assertTrue(newcount > count);
        List<RegionServerThread> regionServerThreads = TEST_UTIL.getHBaseCluster().getRegionServerThreads();
        for (RegionServerThread rs : regionServerThreads) {
            CompactedHFilesDischarger cleaner = new CompactedHFilesDischarger(100, null, rs.getRegionServer(), false);
            cleaner.chore();
            Thread.sleep(1000);
        }
        while (EnvironmentEdgeManager.currentTime() < timeout) {
            int newcount1 = 0;
            for (ColumnFamilyDescriptor colFamily : columnFamilies) {
                newcount1 += hrfs.getStoreFiles(colFamily.getNameAsString()).size();
            }
            if (newcount1 <= 1) {
                break;
            }
            Thread.sleep(50);
        }
        // run CatalogJanitor to clean merge references in hbase:meta and archive the
        // files of merging regions
        int cleaned = 0;
        while (cleaned == 0) {
            cleaned = ADMIN.runCatalogJanitor();
            LOG.debug("catalog janitor returned " + cleaned);
            Thread.sleep(50);
            // Cleanup is async so wait till all procedures are done running.
            ProcedureTestingUtility.waitNoProcedureRunning(TEST_UTIL.getMiniHBaseCluster().getMaster().getMasterProcedureExecutor());
        }
        // We used to check for existence of region in fs but sometimes the region dir was
        // cleaned up by the time we got here making the test sometimes flakey.
        assertTrue(cleaned > 0);
        // Wait around a bit to give stuff a chance to complete.
        while (true) {
            mergedRegionResult = MetaTableAccessor.getRegionResult(TEST_UTIL.getConnection(), mergedRegionInfo);
            if (CatalogFamilyFormat.hasMergeRegions(mergedRegionResult.rawCells())) {
                LOG.info("Waiting on cleanup of merge columns {}", Arrays.asList(mergedRegionResult.rawCells()).stream().map(c -> c.toString()).collect(Collectors.joining(",")));
                Threads.sleep(50);
            } else {
                break;
            }
        }
        assertFalse(CatalogFamilyFormat.hasMergeRegions(mergedRegionResult.rawCells()));
    } finally {
        ADMIN.catalogJanitorSwitch(true);
        TEST_UTIL.deleteTable(tableName);
    }
}

/**
 * This test tests 1, merging region not online; 2, merging same two regions; 3, merging unknown
 * regions. They are in one test case so that we don't have to create many tables, and these tests
 * are simple.
 */
@Test
public void testMerge() throws Exception {
    LOG.info("Starting " + name.getMethodName());
    final TableName tableName = TableName.valueOf(name.getMethodName());
    final Admin admin = TEST_UTIL.getAdmin();
    try {
        // Create table and load data.
        Table table = createTableAndLoadData(MASTER, tableName);
        AssignmentManager am = MASTER.getAssignmentManager();
        List<RegionInfo> regions = am.getRegionStates().getRegionsOfTable(tableName);
        // Fake offline one region
        RegionInfo a = regions.get(0);
        RegionInfo b = regions.get(1);
        am.unassign(b);
        am.offlineRegion(b);
        try {
            // Merge offline region. Region a is offline here
            FutureUtils.get(admin.mergeRegionsAsync(a.getEncodedNameAsBytes(), b.getEncodedNameAsBytes(), false));
            fail("Offline regions should not be able to merge");
        } catch (DoNotRetryRegionException ie) {
            System.out.println(ie);
            assertTrue(ie instanceof MergeRegionException);
        }
        try {
            // Merge the same region: b and b.
            FutureUtils.get(admin.mergeRegionsAsync(b.getEncodedNameAsBytes(), b.getEncodedNameAsBytes(), true));
            fail("A region should not be able to merge with itself, even forcfully");
        } catch (IOException ie) {
            assertTrue("Exception should mention regions not online", StringUtils.stringifyException(ie).contains("region to itself") && ie instanceof MergeRegionException);
        }
        try {
            // Merge unknown regions
            FutureUtils.get(admin.mergeRegionsAsync(Bytes.toBytes("-f1"), Bytes.toBytes("-f2"), true));
            fail("Unknown region could not be merged");
        } catch (IOException ie) {
            assertTrue("UnknownRegionException should be thrown", ie instanceof UnknownRegionException);
        }
        table.close();
    } finally {
        TEST_UTIL.deleteTable(tableName);
    }
}

@Test
public void testMergeWithReplicas() throws Exception {
    final TableName tableName = TableName.valueOf(name.getMethodName());
    try {
        // Create table and load data.
        Table table = createTableAndLoadData(MASTER, tableName, 5, 2);
        List<Pair<RegionInfo, ServerName>> initialRegionToServers = MetaTableAccessor.getTableRegionsAndLocations(TEST_UTIL.getConnection(), tableName);
        // Merge 1st and 2nd region
        PairOfSameType<RegionInfo> mergedRegions = mergeRegionsAndVerifyRegionNum(MASTER, tableName, 0, 2, 5 * 2 - 2);
        List<Pair<RegionInfo, ServerName>> currentRegionToServers = MetaTableAccessor.getTableRegionsAndLocations(TEST_UTIL.getConnection(), tableName);
        List<RegionInfo> initialRegions = new ArrayList<>();
        for (Pair<RegionInfo, ServerName> p : initialRegionToServers) {
            initialRegions.add(p.getFirst());
        }
        List<RegionInfo> currentRegions = new ArrayList<>();
        for (Pair<RegionInfo, ServerName> p : currentRegionToServers) {
            currentRegions.add(p.getFirst());
        }
        // this is the first region
        assertTrue(initialRegions.contains(mergedRegions.getFirst()));
        // this is the replica of the first region
        assertTrue(initialRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getFirst(), 1)));
        // this is the second region
        assertTrue(initialRegions.contains(mergedRegions.getSecond()));
        // this is the replica of the second region
        assertTrue(initialRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getSecond(), 1)));
        // this is the new region
        assertTrue(!initialRegions.contains(currentRegions.get(0)));
        // replica of the new region
        assertTrue(!initialRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(currentRegions.get(0), 1)));
        // replica of the new region
        assertTrue(currentRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(currentRegions.get(0), 1)));
        // replica of the merged region
        assertTrue(!currentRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getFirst(), 1)));
        // replica of the merged region
        assertTrue(!currentRegions.contains(RegionReplicaUtil.getRegionInfoForReplica(mergedRegions.getSecond(), 1)));
        table.close();
    } finally {
        TEST_UTIL.deleteTable(tableName);
    }
}

@Test
public void testDisableAndMove() throws Exception {
    Admin admin = TEST_UTIL.getAdmin();
    // Create a table with more than one region
    Table t = TEST_UTIL.createMultiRegionTable(tableName, Bytes.toBytes(F1), 10);
    TEST_UTIL.waitUntilAllRegionsAssigned(tableName);
    // Write an update to each region
    for (RegionInfo regionInfo : admin.getRegions(tableName)) {
        byte[] startKey = regionInfo.getStartKey();
        // The startKey of the first region is "empty", which would throw an error if we try to
        // Put that.
        byte[] rowKey = org.apache.hbase.thirdparty.com.google.common.primitives.Bytes.concat(startKey, Bytes.toBytes("1"));
        Put p = new Put(rowKey);
        p.addColumn(Bytes.toBytes(F1), Bytes.toBytes("q1"), Bytes.toBytes("value"));
        t.put(p);
    }
    // Get a Region which is on the first RS
    HRegionServer rs1 = TEST_UTIL.getRSForFirstRegionInTable(tableName);
    HRegionServer rs2 = TEST_UTIL.getOtherRegionServer(rs1);
    List<RegionInfo> regionsOnRS1ForTable = admin.getRegions(rs1.getServerName()).stream().filter((regionInfo) -> regionInfo.getTable().equals(tableName)).collect(Collectors.toList());
    assertTrue("Expected to find at least one region for " + tableName + " on " + rs1.getServerName() + ", but found none", !regionsOnRS1ForTable.isEmpty());
    final RegionInfo regionToMove = regionsOnRS1ForTable.get(0);
    // Offline the region and then try to move it. Should fail.
    admin.unassign(regionToMove.getRegionName(), true);
    try {
        admin.move(regionToMove.getEncodedNameAsBytes(), rs2.getServerName());
        fail();
    } catch (DoNotRetryRegionException e) {
        // We got expected exception
    }
    // Reassign for next stage of test.
    admin.assign(regionToMove.getRegionName());
    // Disable the table
    admin.disableTable(tableName);
    try {
        // Move the region to the other RS -- should fail
        admin.move(regionToMove.getEncodedNameAsBytes(), rs2.getServerName());
        fail();
    } catch (DoNotRetryIOException e) {
        // We got expected exception
    }
}

