@Test
public void testSecondaryReplicaReadEnabled() throws Exception {
    tableName = name.getTableName();
    TableDescriptor tableDescriptor = TableDescriptorBuilder.newBuilder(tableName).setRegionReplication(2).setColumnFamily(ColumnFamilyDescriptorBuilder.of(FAMILY)).setRegionMemStoreReplication(true).build();
    HTU.getAdmin().createTable(tableDescriptor);
    final ArrayList<Pair<HRegion, HRegionServer>> regionAndRegionServers = new ArrayList<Pair<HRegion, HRegionServer>>(Arrays.asList(null, null));
    for (int i = 0; i < 2; i++) {
        HRegionServer rs = HTU.getMiniHBaseCluster().getRegionServer(i);
        List<HRegion> onlineRegions = rs.getRegions(tableName);
        for (HRegion region : onlineRegions) {
