@Test
public void testRowLock() throws IOException {
    TableDescriptor hdt = TEST_UTIL.createModifyableTableDescriptor(testName.getMethodName()).setCoprocessor(SleepCoprocessor.class.getName()).build();
    TEST_UTIL.createTable(hdt, new byte[][] { FAM }, TEST_UTIL.getConfiguration());
    TableName tableName = hdt.getTableName();
    Thread incrementThread = new Thread(() -> {
        try {
            try (Table table = TEST_UTIL.getConnection().getTable(tableName)) {
                table.incrementColumnValue(ROW1, FAM, FAM, 1);
            }
        } catch (IOException e) {
            Assert.fail(e.getMessage());
        }
    });
    Thread getThread = new Thread(() -> {
        try (Table table = TEST_UTIL.getConnection().getTableBuilder(tableName, null).setRpcTimeout(1000).build()) {
            Delete delete = new Delete(ROW1);
            table.delete(delete);
        } catch (IOException e) {
            Assert.fail(e.getMessage());
        }
    });
    incrementThread.start();
    Threads.sleep(1000);
    getThread.start();
    Threads.sleep(2000);
    try (Table table = TEST_UTIL.getConnection().getTableBuilder(tableName, null).setRpcTimeout(1000).build()) {
        // We have only two handlers. The first thread will get a write lock for row1 and occupy
        // the first handler. The second thread need a read lock for row1, it should quit after 1000
        // ms and give back the handler because it can not get the lock in time.
        // So we can get the value using the second handler.
        // Will throw exception if the timeout checking is failed
        table.get(new Get(ROW2));
    } finally {
        incrementThread.interrupt();
        getThread.interrupt();
    }
}

@Test
public void test() throws Exception {
    UTIL.createMultiRegionTable(TABLE_NAME, CF);
    try (Table table = UTIL.getConnection().getTable(TABLE_NAME)) {
        UTIL.loadTable(table, CF);
    }
    int numRegions = UTIL.getMiniHBaseCluster().getRegions(TABLE_NAME).size();
    RegionServerThread rst0 = UTIL.getMiniHBaseCluster().getRegionServerThreads().get(0);
    RegionServerThread rst1 = UTIL.getMiniHBaseCluster().getRegionServerThreads().get(1);
    HRegionServer liveRS;
    RegionServerThread toKillRSThread;
    if (rst1.getRegionServer().getRegions(TableName.META_TABLE_NAME).isEmpty()) {
        liveRS = rst0.getRegionServer();
