@Test
public void test() throws IOException, InterruptedException {
    final HRegionServer rs = testUtil.getRSForFirstRegionInTable(tableName);
    final HRegion region = (HRegion) rs.getRegions(tableName).get(0);
    HRegion spiedRegion = spy(region);
    final MutableBoolean flushed = new MutableBoolean(false);
    final MutableBoolean reported = new MutableBoolean(false);
    doAnswer(new Answer<FlushResult>() {

        @Override
        public FlushResult answer(InvocationOnMock invocation) throws Throwable {
            synchronized (flushed) {
                flushed.setValue(true);
                flushed.notifyAll();
            }
            synchronized (reported) {
                while (!reported.booleanValue()) {
                    reported.wait();
                }
            }
            rs.getWAL(region.getRegionInfo()).abortCacheFlush(region.getRegionInfo().getEncodedNameAsBytes());
            throw new DroppedSnapshotException("testcase");
        }
    }).when(spiedRegion).internalFlushCacheAndCommit(any(), any(), any(), any());
    // Find region key; don't pick up key for hbase:meta by mistake.
    String key = null;
    for (Map.Entry<String, HRegion> entry : rs.getOnlineRegions().entrySet()) {
        if (entry.getValue().getRegionInfo().getTable().equals(this.tableName)) {
            key = entry.getKey();
            break;
        }
    }
    rs.getOnlineRegions().put(key, spiedRegion);
    Connection conn = testUtil.getConnection();
    try (Table table = conn.getTable(tableName)) {
        table.put(new Put(Bytes.toBytes("row0")).addColumn(family, qualifier, Bytes.toBytes("val0")));
    }
    long oldestSeqIdOfStore = region.getOldestSeqIdOfStore(family);
    LOG.info("CHANGE OLDEST " + oldestSeqIdOfStore);
    assertTrue(oldestSeqIdOfStore > HConstants.NO_SEQNUM);
    rs.getMemStoreFlusher().requestFlush(spiedRegion, FlushLifeCycleTracker.DUMMY);
    synchronized (flushed) {
        while (!flushed.booleanValue()) {
            flushed.wait();
        }
    }
    try (Table table = conn.getTable(tableName)) {
        table.put(new Put(Bytes.toBytes("row1")).addColumn(family, qualifier, Bytes.toBytes("val1")));
    }
    long now = EnvironmentEdgeManager.currentTime();
    rs.tryRegionServerReport(now - 500, now);
    synchronized (reported) {
        reported.setValue(true);
        reported.notifyAll();
    }
    while (testUtil.getRSForFirstRegionInTable(tableName) == rs) {
        Thread.sleep(100);
    }
    try (Table table = conn.getTable(tableName)) {
        Result result = table.get(new Get(Bytes.toBytes("row0")));
        assertArrayEquals(Bytes.toBytes("val0"), result.getValue(family, qualifier));
    }
}

@Test
public void testSplitIgnoreBlockingFiles() throws Exception {
    ADMIN.splitSwitch(false, true);
    byte[] value = new byte[1024];
    for (int m = 0; m < 10; m++) {
        String rowPrefix = "row" + m;
        for (int i = 0; i < 10; i++) {
            Put p = new Put(Bytes.toBytes(rowPrefix + i));
            p.addColumn(CF, Bytes.toBytes("qualifier"), value);
            p.addColumn(CF, Bytes.toBytes("qualifier2"), value);
            TABLE.put(p);
        }
        ADMIN.flush(TABLE_NAME);
    }
    Scan scan = new Scan();
    ResultScanner results = TABLE.getScanner(scan);
    int count = 0;
    while (results.next() != null) {
        count++;
    }
    Assert.assertEquals("There should be 100 rows!", 100, count);
    List<HRegion> regions = UTIL.getMiniHBaseCluster().getRegionServer(0).getRegions();
    regions.removeIf(r -> !r.getRegionInfo().getTable().equals(TABLE_NAME));
    assertEquals(1, regions.size());
    assertNotNull(regions.get(0).getSplitPolicy().getSplitPoint());
    assertTrue(regions.get(0).getCompactPriority() >= PRIORITY_USER);
    assertTrue(UTIL.getMiniHBaseCluster().getRegionServer(0).getCompactSplitThread().requestSplit(regions.get(0)));
    // split region
    ADMIN.splitSwitch(true, true);
    MasterProcedureEnv env = UTIL.getMiniHBaseCluster().getMaster().getMasterProcedureExecutor().getEnvironment();
    final ProcedureExecutor<MasterProcedureEnv> executor = UTIL.getMiniHBaseCluster().getMaster().getMasterProcedureExecutor();
    SplitTableRegionProcedure splitProcedure = new SplitTableRegionProcedure(env, regions.get(0).getRegionInfo(), Bytes.toBytes("row5"));
    executor.submitProcedure(splitProcedure);
    ProcedureTestingUtility.waitProcedure(executor, splitProcedure.getProcId());
    regions = UTIL.getMiniHBaseCluster().getRegionServer(0).getRegions();
    regions.removeIf(r -> !r.getRegionInfo().getTable().equals(TABLE_NAME));
    assertEquals(2, regions.size());
    scan = new Scan();
    results = TABLE.getScanner(scan);
    count = 0;
    while (results.next() != null) {
        count++;
    }
    Assert.assertEquals("There should be 100 rows!", 100, count);
    for (HRegion region : regions) {
        assertTrue(region.getCompactPriority() < PRIORITY_USER);
        assertFalse(UTIL.getMiniHBaseCluster().getRegionServer(0).getCompactSplitThread().requestSplit(region));
    }
}

