@Test
public void testDeleteMarkerLongevity() throws Exception {
    try {
        final long now = EnvironmentEdgeManager.currentTime();
        EnvironmentEdgeManagerTestHelper.injectEdge(new EnvironmentEdge() {

            @Override
            public long currentTime() {
                return now;
            }
        });
        // @formatter:off
        KeyValue[] kvs = new KeyValue[] { /*0*/
        new KeyValue(Bytes.toBytes("R1"), Bytes.toBytes("cf"), null, now - 100, // live
        KeyValue.Type.DeleteFamily), /*1*/
        new KeyValue(Bytes.toBytes("R1"), Bytes.toBytes("cf"), null, now - 1000, // expired
        KeyValue.Type.DeleteFamily), /*2*/
        create("R1", "cf", "a", now - 50, KeyValue.Type.Put, // live
        "v3"), /*3*/
        create("R1", "cf", "a", now - 55, KeyValue.Type.Delete, // live
        "dontcare"), /*4*/
        create("R1", "cf", "a", now - 55, KeyValue.Type.Put, // deleted
        "deleted-version v2"), /*5*/
        create("R1", "cf", "a", now - 60, KeyValue.Type.Put, // live
        "v1"), /*6*/
        create("R1", "cf", "a", now - 65, KeyValue.Type.Put, // max-version reached
        "v0"), /*7*/
        create("R1", "cf", "a", now - 100, KeyValue.Type.DeleteColumn, // max-version
        "dont-care"), /*8*/
        create("R1", "cf", "b", now - 600, KeyValue.Type.DeleteColumn, // expired
        "dont-care"), /*9*/
        create("R1", "cf", "b", now - 70, KeyValue.Type.Put, // live
        "v2"), /*10*/
        create("R1", "cf", "b", now - 750, KeyValue.Type.Put, // expired
        "v1"), /*11*/
        create("R1", "cf", "c", now - 500, KeyValue.Type.Delete, // expired
        "dontcare"), /*12*/
        create("R1", "cf", "c", now - 600, KeyValue.Type.Put, // expired
        "v1"), /*13*/
        create("R1", "cf", "c", now - 1000, KeyValue.Type.Delete, // expired
        "dontcare"), /*14*/
        create("R1", "cf", "d", now - 60, KeyValue.Type.Put, // live
        "expired put"), /*15*/
        create("R1", "cf", "d", now - 100, KeyValue.Type.Delete, // live
        "not-expired delete") };
        // @formatter:on
        List<KeyValueScanner> scanners = scanFixture(kvs);
        ScanInfo scanInfo = new ScanInfo(CONF, Bytes.toBytes("cf"), 0, /* minVersions */
        2, /* maxVersions */
        500, /* ttl */
        KeepDeletedCells.FALSE, /* keepDeletedCells */
        HConstants.DEFAULT_BLOCKSIZE, /* block size */
        200, /* timeToPurgeDeletes */
        CellComparator.getInstance(), false);
        try (StoreScanner scanner = new StoreScanner(scanInfo, 2, ScanType.COMPACT_DROP_DELETES, scanners)) {
            List<Cell> results = new ArrayList<>();
            results = new ArrayList<>();
            assertEquals(true, scanner.next(results));
            assertEquals(kvs[0], results.get(0));
            assertEquals(kvs[2], results.get(1));
            assertEquals(kvs[3], results.get(2));
            assertEquals(kvs[5], results.get(3));
            assertEquals(kvs[9], results.get(4));
            assertEquals(kvs[14], results.get(5));
            assertEquals(kvs[15], results.get(6));
            assertEquals(7, results.size());
        }
    } finally {
        EnvironmentEdgeManagerTestHelper.reset();
    }
}

