@Test
public void testScannersClosedWhenCheckingOnlyMemStore() throws IOException {
    class MyCollectionBackedScanner extends CollectionBackedScanner {

        final boolean fileScanner;

        boolean closed;

        MyCollectionBackedScanner(boolean fileScanner) {
            super(Collections.emptySortedSet());
            this.fileScanner = fileScanner;
        }

        @Override
        public boolean isFileScanner() {
            return fileScanner;
        }

        @Override
        public void close() {
            super.close();
            closed = true;
        }
    }
    ScanInfo scanInfo = new ScanInfo(CONF, CF, 0, 1, Long.MAX_VALUE, KeepDeletedCells.FALSE, HConstants.DEFAULT_BLOCKSIZE, 0, CellComparator.getInstance(), false);
    InternalScan scan = new InternalScan(new Scan());
    scan.checkOnlyMemStore();
    MyCollectionBackedScanner fileScanner = new MyCollectionBackedScanner(true);
    MyCollectionBackedScanner memStoreScanner = new MyCollectionBackedScanner(false);
    List<? extends KeyValueScanner> allScanners = Arrays.asList(fileScanner, memStoreScanner);
    try (StoreScanner scanner = new StoreScanner(scan, scanInfo, null, allScanners)) {
        List<KeyValueScanner> remaining = scanner.selectScannersFrom(null, allScanners);
        assertEquals(1, remaining.size());
        assertSame(memStoreScanner, remaining.get(0));
        assertTrue(fileScanner.closed);
        assertFalse(memStoreScanner.closed);
    }
}

@Test
public void testScannerCloseAndUpdateReadersWithMemstoreScanner() throws Exception {
    Put p = new Put(Bytes.toBytes("row"));
    p.addColumn(fam, Bytes.toBytes("q1"), Bytes.toBytes("val"));
    region.put(p);
    // create the store scanner here.
    // for easiness, use Long.MAX_VALUE as read pt
    try (ExtendedStoreScanner scan = new ExtendedStoreScanner(region.getStore(fam), scanInfo, new Scan(), getCols("q1"), Long.MAX_VALUE)) {
        p = new Put(Bytes.toBytes("row1"));
        p.addColumn(fam, Bytes.toBytes("q1"), Bytes.toBytes("val"));
        region.put(p);
        HStore store = region.getStore(fam);
        // use the lock to manually get a new memstore scanner. this is what
        // HStore#notifyChangedReadersObservers does under the lock.(lock is not needed here
        // since it is just a testcase).
        store.getStoreEngine().readLock();
        final List<KeyValueScanner> memScanners = store.memstore.getScanners(Long.MAX_VALUE);
        store.getStoreEngine().readUnlock();
        Thread closeThread = new Thread() {

            public void run() {
                // close should be completed
                scan.close(false, true);
            }
        };
        closeThread.start();
        Thread updateThread = new Thread() {

            public void run() {
                try {
                    // use the updated memstoreScanners and pass it to updateReaders
                    scan.updateReaders(true, Collections.emptyList(), memScanners);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        };
        updateThread.start();
        // wait for close and updateThread to complete
        closeThread.join();
        updateThread.join();
        MemStoreLAB memStoreLAB;
        for (KeyValueScanner scanner : memScanners) {
            if (scanner instanceof SegmentScanner) {
                memStoreLAB = ((SegmentScanner) scanner).segment.getMemStoreLAB();
                if (memStoreLAB != null) {
                    // There should be no unpooled chunks
                    int refCount = ((MemStoreLABImpl) memStoreLAB).getRefCntValue();
                    assertTrue("The memstore should not have unpooled chunks", refCount == 0);
                }
            }
        }
    }
}

