@Test
public void testGetSeek() throws IOException {
    StoreFileScanner.instrument();
    prepareRegion();
    Get g = new Get(RK_BYTES);
    final TimestampsFilter timestampsFilter = new TimestampsFilter(ImmutableList.of(5L), true);
