    Connection conn = ConnectionFactory.createConnection(conf);
    try {
        TEST_UTIL.getAdmin().createTable(TableDescriptorBuilder.newBuilder(tableName).setColumnFamily(ColumnFamilyDescriptorBuilder.of(family)).setCompactionEnabled(false).build());
        TEST_UTIL.waitTableAvailable(tableName);
        HRegionServer regionServer = TEST_UTIL.getRSForFirstRegionInTable(tableName);
        PressureAwareCompactionThroughputController throughputController = (PressureAwareCompactionThroughputController) regionServer.getCompactSplitThread().getCompactionThroughputController();
        assertEquals(10L * 1024 * 1024, throughputController.getMaxThroughput(), EPSILON);
        Table table = conn.getTable(tableName);
        for (int i = 0; i < 5; i++) {
            byte[] value = new byte[0];
            table.put(new Put(Bytes.toBytes(i)).addColumn(family, qualifier, value));
            TEST_UTIL.flush(tableName);
        }
