/**
 * Tests the case where a RegionServer enters a GC pause, comes back online after the master
 * declared it dead and started to split. Want log rolling after a master split to fail. See
 * HBASE-2312.
 */
@Test
public void testLogRollAfterSplitStart() throws IOException {
    LOG.info("Verify wal roll after split starts will fail.");
    String logName = ServerName.valueOf("testLogRollAfterSplitStart", 16010, EnvironmentEdgeManager.currentTime()).toString();
    Path thisTestsDir = new Path(HBASELOGDIR, AbstractFSWALProvider.getWALDirectoryName(logName));
    final WALFactory wals = new WALFactory(conf, logName);
    try {
        // put some entries in an WAL
        TableName tableName = TableName.valueOf(this.getClass().getName());
        RegionInfo regionInfo = RegionInfoBuilder.newBuilder(tableName).build();
        WAL log = wals.getWAL(regionInfo);
        MultiVersionConcurrencyControl mvcc = new MultiVersionConcurrencyControl(1);
        int total = 20;
        for (int i = 0; i < total; i++) {
            WALEdit kvs = new WALEdit();
            kvs.add(new KeyValue(Bytes.toBytes(i), tableName.getName(), tableName.getName()));
            NavigableMap<byte[], Integer> scopes = new TreeMap<>(Bytes.BYTES_COMPARATOR);
            scopes.put(Bytes.toBytes("column"), 0);
            log.appendData(regionInfo, new WALKeyImpl(regionInfo.getEncodedNameAsBytes(), tableName, EnvironmentEdgeManager.currentTime(), mvcc, scopes), kvs);
        }
        // Send the data to HDFS datanodes and close the HDFS writer
        log.sync();
        closeWriter((AbstractFSWAL<?>) log);
        // code taken from MasterFileSystem.getLogDirs(), which is called from
        // MasterFileSystem.splitLog() handles RS shutdowns (as observed by the splitting process)
        // rename the directory so a rogue RS doesn't create more WALs
        Path rsSplitDir = thisTestsDir.suffix(AbstractFSWALProvider.SPLITTING_EXT);
        if (!fs.rename(thisTestsDir, rsSplitDir)) {
            throw new IOException("Failed fs.rename for log split: " + thisTestsDir);
        }
        LOG.debug("Renamed region directory: " + rsSplitDir);
        LOG.debug("Processing the old log files.");
        WALSplitter.split(HBASELOGDIR, rsSplitDir, OLDLOGDIR, fs, conf, wals);
        LOG.debug("Trying to roll the WAL.");
        IOException error = assertThrows(IOException.class, () -> log.rollWriter());
        if (error instanceof RemoteException) {
            error = ((RemoteException) error).unwrapRemoteException();
        }
        assertTrue("unexpected error: " + Throwables.getStackTraceAsString(error), error instanceof FileNotFoundException || error.getCause() instanceof FileNotFoundException);
    } finally {
        wals.close();
        if (fs.exists(thisTestsDir)) {
            fs.delete(thisTestsDir, true);
        }
    }
}

@Test
public void testSlowSyncLogRolling() throws Exception {
    // Create the test table
    TableDescriptor desc = TableDescriptorBuilder.newBuilder(TableName.valueOf(getName())).setColumnFamily(ColumnFamilyDescriptorBuilder.of(HConstants.CATALOG_FAMILY)).build();
    admin.createTable(desc);
    Table table = TEST_UTIL.getConnection().getTable(desc.getTableName());
    int row = 1;
    try {
        // Get a reference to the FSHLog
        server = TEST_UTIL.getRSForFirstRegionInTable(desc.getTableName());
        RegionInfo region = server.getRegions(desc.getTableName()).get(0).getRegionInfo();
        final FSHLog log = (FSHLog) server.getWAL(region);
        // Register a WALActionsListener to observe if a SLOW_SYNC roll is requested
        final AtomicBoolean slowSyncHookCalled = new AtomicBoolean();
        log.registerWALActionsListener(new WALActionsListener() {

            @Override
            public void logRollRequested(WALActionsListener.RollRequestReason reason) {
                switch(reason) {
                    case SLOW_SYNC:
                        slowSyncHookCalled.lazySet(true);
                        break;
                    default:
                        break;
                }
            }
        });
        // Write some data
        for (int i = 0; i < 10; i++) {
            writeData(table, row++);
        }
        assertFalse("Should not have triggered log roll due to SLOW_SYNC", slowSyncHookCalled.get());
        // Set up for test
        slowSyncHookCalled.set(false);
        // Wrap the current writer with the anonymous class below that adds 200 ms of
        // latency to any sync on the hlog. This should be more than sufficient to trigger
        // slow sync warnings.
        final Writer oldWriter1 = log.getWriter();
        final Writer newWriter1 = new Writer() {

            @Override
            public void close() throws IOException {
                oldWriter1.close();
            }

            @Override
            public void sync(boolean forceSync) throws IOException {
                try {
                    Thread.sleep(200);
                } catch (InterruptedException e) {
                    InterruptedIOException ex = new InterruptedIOException();
                    ex.initCause(e);
                    throw ex;
                }
                oldWriter1.sync(forceSync);
            }

            @Override
            public void append(Entry entry) throws IOException {
                oldWriter1.append(entry);
            }

            @Override
            public long getLength() {
                return oldWriter1.getLength();
            }

            @Override
            public long getSyncedLength() {
                return oldWriter1.getSyncedLength();
            }
        };
        log.setWriter(newWriter1);
        // Write some data.
        // We need to write at least 5 times, but double it. We should only request
        // a SLOW_SYNC roll once in the current interval.
        for (int i = 0; i < 10; i++) {
            writeData(table, row++);
        }
        // Wait for our wait injecting writer to get rolled out, as needed.
        TEST_UTIL.waitFor(10000, 100, new Waiter.ExplainingPredicate<Exception>() {

            @Override
            public boolean evaluate() throws Exception {
                return log.getWriter() != newWriter1;
            }

            @Override
            public String explainFailure() throws Exception {
                return "Waited too long for our test writer to get rolled out";
            }
        });
        assertTrue("Should have triggered log roll due to SLOW_SYNC", slowSyncHookCalled.get());
        // Set up for test
        slowSyncHookCalled.set(false);
        // Wrap the current writer with the anonymous class below that adds 5000 ms of
        // latency to any sync on the hlog.
        // This will trip the other threshold.
        final Writer oldWriter2 = (Writer) log.getWriter();
        final Writer newWriter2 = new Writer() {

            @Override
            public void close() throws IOException {
                oldWriter2.close();
            }

            @Override
            public void sync(boolean forceSync) throws IOException {
                try {
                    Thread.sleep(5000);
                } catch (InterruptedException e) {
                    InterruptedIOException ex = new InterruptedIOException();
                    ex.initCause(e);
                    throw ex;
                }
                oldWriter2.sync(forceSync);
            }

            @Override
            public void append(Entry entry) throws IOException {
                oldWriter2.append(entry);
            }

            @Override
            public long getLength() {
                return oldWriter2.getLength();
            }

            @Override
            public long getSyncedLength() {
                return oldWriter2.getSyncedLength();
            }
        };
        log.setWriter(newWriter2);
        // Write some data. Should only take one sync.
        writeData(table, row++);
        // Wait for our wait injecting writer to get rolled out, as needed.
        TEST_UTIL.waitFor(10000, 100, new Waiter.ExplainingPredicate<Exception>() {

            @Override
            public boolean evaluate() throws Exception {
                return log.getWriter() != newWriter2;
            }

            @Override
            public String explainFailure() throws Exception {
                return "Waited too long for our test writer to get rolled out";
            }
        });
        assertTrue("Should have triggered log roll due to SLOW_SYNC", slowSyncHookCalled.get());
        // Set up for test
        slowSyncHookCalled.set(false);
        // Write some data
        for (int i = 0; i < 10; i++) {
            writeData(table, row++);
        }
        assertFalse("Should not have triggered log roll due to SLOW_SYNC", slowSyncHookCalled.get());
    } finally {
        table.close();
    }
}

/**
 * Tests that logs are rolled upon detecting datanode death Requires an HDFS jar with HDFS-826 &
 * syncFs() support (HDFS-200)
 */
@Test
public void testLogRollOnDatanodeDeath() throws Exception {
    Long oldValue = TEST_UTIL.getConfiguration().getLong("hbase.regionserver.hlog.check.lowreplication.interval", -1);
    try {
        /**
         * When we reuse the code of AsyncFSWAL to FSHLog, the low replication is only checked by
         * {@link LogRoller#checkLowReplication},so in order to make this test spend less time,we
         * should minimize following config which is maximized by
         * {@link AbstractTestLogRolling#setUpBeforeClass}
         */
        TEST_UTIL.getConfiguration().setLong("hbase.regionserver.hlog.check.lowreplication.interval", 1000);
        this.tearDown();
        this.setUp();
        TEST_UTIL.ensureSomeRegionServersAvailable(2);
        assertTrue("This test requires WAL file replication set to 2.", fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()) == 2);
        LOG.info("Replication=" + fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()));
        this.server = cluster.getRegionServer(0);
        // Create the test table and open it
        TableDescriptor desc = TableDescriptorBuilder.newBuilder(TableName.valueOf(getName())).setColumnFamily(ColumnFamilyDescriptorBuilder.of(HConstants.CATALOG_FAMILY)).build();
        admin.createTable(desc);
        Table table = TEST_UTIL.getConnection().getTable(desc.getTableName());
        server = TEST_UTIL.getRSForFirstRegionInTable(desc.getTableName());
        RegionInfo region = server.getRegions(desc.getTableName()).get(0).getRegionInfo();
        final FSHLog log = (FSHLog) server.getWAL(region);
        final AtomicBoolean lowReplicationHookCalled = new AtomicBoolean(false);
        log.registerWALActionsListener(new WALActionsListener() {

            @Override
            public void logRollRequested(WALActionsListener.RollRequestReason reason) {
                switch(reason) {
                    case LOW_REPLICATION:
                        lowReplicationHookCalled.lazySet(true);
                        break;
                    default:
                        break;
                }
            }
        });
        // add up the datanode count, to ensure proper replication when we kill 1
        // This function is synchronous; when it returns, the dfs cluster is active
        // We start 3 servers and then stop 2 to avoid a directory naming conflict
        // when we stop/start a namenode later, as mentioned in HBASE-5163
        List<DataNode> existingNodes = dfsCluster.getDataNodes();
        int numDataNodes = 3;
        TEST_UTIL.getConfiguration().setLong("hbase.regionserver.hlog.check.lowreplication.interval", 1000);
        dfsCluster.startDataNodes(TEST_UTIL.getConfiguration(), numDataNodes, true, null, null);
        List<DataNode> allNodes = dfsCluster.getDataNodes();
        for (int i = allNodes.size() - 1; i >= 0; i--) {
            if (existingNodes.contains(allNodes.get(i))) {
                dfsCluster.stopDataNode(i);
            }
        }
        assertTrue("DataNodes " + dfsCluster.getDataNodes().size() + " default replication " + fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()), dfsCluster.getDataNodes().size() >= fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()) + 1);
        writeData(table, 2);
        long curTime = EnvironmentEdgeManager.currentTime();
        LOG.info("log.getCurrentFileName(): " + log.getCurrentFileName());
        long oldFilenum = AbstractFSWALProvider.extractFileNumFromWAL(log);
        assertTrue("Log should have a timestamp older than now", curTime > oldFilenum && oldFilenum != -1);
        assertTrue("The log shouldn't have rolled yet", oldFilenum == AbstractFSWALProvider.extractFileNumFromWAL(log));
        final DatanodeInfo[] pipeline = log.getPipeline();
        assertTrue(pipeline.length == fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()));
        // kill a datanode in the pipeline to force a log roll on the next sync()
        // This function is synchronous, when it returns the node is killed.
        assertTrue(dfsCluster.stopDataNode(pipeline[0].getName()) != null);
        // this write should succeed, but trigger a log roll
        writeData(table, 2);
        TEST_UTIL.waitFor(10000, 100, () -> {
            long newFilenum = AbstractFSWALProvider.extractFileNumFromWAL(log);
            return newFilenum > oldFilenum && newFilenum > curTime && lowReplicationHookCalled.get();
        });
        long newFilenum = AbstractFSWALProvider.extractFileNumFromWAL(log);
        // write some more log data (this should use a new hdfs_out)
        writeData(table, 3);
        assertTrue("The log should not roll again.", AbstractFSWALProvider.extractFileNumFromWAL(log) == newFilenum);
        // kill another datanode in the pipeline, so the replicas will be lower than
        // the configured value 2.
        assertTrue(dfsCluster.stopDataNode(pipeline[1].getName()) != null);
        batchWriteAndWait(table, log, 3, false, 14000);
        int replication = log.getLogReplication();
        assertTrue("LowReplication Roller should've been disabled, current replication=" + replication, !log.isLowReplicationRollEnabled());
        dfsCluster.startDataNodes(TEST_UTIL.getConfiguration(), 1, true, null, null);
        // Force roll writer. The new log file will have the default replications,
        // and the LowReplication Roller will be enabled.
        log.rollWriter(true);
        batchWriteAndWait(table, log, 13, true, 10000);
        replication = log.getLogReplication();
        assertTrue("New log file should have the default replication instead of " + replication, replication == fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()));
        assertTrue("LowReplication Roller should've been enabled", log.isLowReplicationRollEnabled());
    } finally {
        TEST_UTIL.getConfiguration().setLong("hbase.regionserver.hlog.check.lowreplication.interval", oldValue);
    }
}

/**
 * Test that WAL is rolled when all data nodes in the pipeline have been restarted.
 */
@Test
public void testLogRollOnPipelineRestart() throws Exception {
    LOG.info("Starting testLogRollOnPipelineRestart");
    assertTrue("This test requires WAL file replication.", fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()) > 1);
    LOG.info("Replication=" + fs.getDefaultReplication(TEST_UTIL.getDataTestDirOnTestFS()));
    // When the hbase:meta table can be opened, the region servers are running
    Table t = TEST_UTIL.getConnection().getTable(TableName.META_TABLE_NAME);
    try {
        this.server = cluster.getRegionServer(0);
        // Create the test table and open it
        TableDescriptor desc = TableDescriptorBuilder.newBuilder(TableName.valueOf(getName())).setColumnFamily(ColumnFamilyDescriptorBuilder.of(HConstants.CATALOG_FAMILY)).build();
        admin.createTable(desc);
        Table table = TEST_UTIL.getConnection().getTable(desc.getTableName());
        server = TEST_UTIL.getRSForFirstRegionInTable(desc.getTableName());
        RegionInfo region = server.getRegions(desc.getTableName()).get(0).getRegionInfo();
        final WAL log = server.getWAL(region);
        final List<Path> paths = new ArrayList<>(1);
        final List<Integer> preLogRolledCalled = new ArrayList<>();
        paths.add(AbstractFSWALProvider.getCurrentFileName(log));
        log.registerWALActionsListener(new WALActionsListener() {

            @Override
            public void preLogRoll(Path oldFile, Path newFile) {
                LOG.debug("preLogRoll: oldFile=" + oldFile + " newFile=" + newFile);
                preLogRolledCalled.add(new Integer(1));
            }

            @Override
            public void postLogRoll(Path oldFile, Path newFile) {
                paths.add(newFile);
            }
        });
        writeData(table, 1002);
        long curTime = EnvironmentEdgeManager.currentTime();
        LOG.info("log.getCurrentFileName()): " + AbstractFSWALProvider.getCurrentFileName(log));
        long oldFilenum = AbstractFSWALProvider.extractFileNumFromWAL(log);
        assertTrue("Log should have a timestamp older than now", curTime > oldFilenum && oldFilenum != -1);
        assertTrue("The log shouldn't have rolled yet", oldFilenum == AbstractFSWALProvider.extractFileNumFromWAL(log));
        // roll all datanodes in the pipeline
        dfsCluster.restartDataNodes();
        Thread.sleep(1000);
        dfsCluster.waitActive();
        LOG.info("Data Nodes restarted");
        validateData(table, 1002);
        // this write should succeed, but trigger a log roll
        writeData(table, 1003);
        long newFilenum = AbstractFSWALProvider.extractFileNumFromWAL(log);
        assertTrue("Missing datanode should've triggered a log roll", newFilenum > oldFilenum && newFilenum > curTime);
        validateData(table, 1003);
        writeData(table, 1004);
        // roll all datanode again
        dfsCluster.restartDataNodes();
        Thread.sleep(1000);
        dfsCluster.waitActive();
        LOG.info("Data Nodes restarted");
        validateData(table, 1004);
        // this write should succeed, but trigger a log roll
        writeData(table, 1005);
        // force a log roll to read back and verify previously written logs
        log.rollWriter(true);
        assertTrue("preLogRolledCalled has size of " + preLogRolledCalled.size(), preLogRolledCalled.size() >= 1);
        // read back the data written
        Set<String> loggedRows = new HashSet<>();
        for (Path p : paths) {
            LOG.debug("recovering lease for " + p);
            RecoverLeaseFSUtils.recoverFileLease(((HFileSystem) fs).getBackingFs(), p, TEST_UTIL.getConfiguration(), null);
            LOG.debug("Reading WAL " + CommonFSUtils.getPath(p));
            try (WALStreamReader reader = WALFactory.createStreamReader(fs, p, TEST_UTIL.getConfiguration())) {
                WAL.Entry entry;
                while ((entry = reader.next()) != null) {
                    LOG.debug("#" + entry.getKey().getSequenceId() + ": " + entry.getEdit().getCells());
                    for (Cell cell : entry.getEdit().getCells()) {
                        loggedRows.add(Bytes.toStringBinary(cell.getRowArray(), cell.getRowOffset(), cell.getRowLength()));
                    }
                }
            } catch (EOFException e) {
                LOG.debug("EOF reading file " + CommonFSUtils.getPath(p));
            }
        }
        // verify the written rows are there
        assertTrue(loggedRows.contains("row1002"));
        assertTrue(loggedRows.contains("row1003"));
        assertTrue(loggedRows.contains("row1004"));
        assertTrue(loggedRows.contains("row1005"));
        // flush all regions
        for (HRegion r : server.getOnlineRegionsLocalContext()) {
            try {
                r.flush(true);
            } catch (Exception e) {
                // This try/catch was added by HBASE-14317. It is needed
                // because this issue tightened up the semantic such that
                // a failed append could not be followed by a successful
                // sync. What is coming out here is a failed sync, a sync
                // that used to 'pass'.
                LOG.info(e.toString(), e);
            }
        }
        ResultScanner scanner = table.getScanner(new Scan());
        try {
            for (int i = 2; i <= 5; i++) {
                Result r = scanner.next();
                assertNotNull(r);
                assertFalse(r.isEmpty());
                assertEquals("row100" + i, Bytes.toString(r.getRow()));
            }
        } finally {
            scanner.close();
        }
        // verify that no region servers aborted
        for (JVMClusterUtil.RegionServerThread rsThread : TEST_UTIL.getHBaseCluster().getRegionServerThreads()) {
            assertFalse(rsThread.getRegionServer().isAborted());
        }
    } finally {
        if (t != null)
            t.close();
    }
}

/**
 * Spin up a bunch of threads and have them all append to a WAL. Roll the WAL frequently to try
 * and trigger NPE.
 */
@Test
public void testContendedLogRolling() throws Exception {
    TEST_UTIL.startMiniDFSCluster(3);
    Path dir = TEST_UTIL.getDataTestDirOnTestFS();
    // The implementation needs to know the 'handler' count.
    TEST_UTIL.getConfiguration().setInt(HConstants.REGION_SERVER_HANDLER_COUNT, NUM_THREADS);
    final Configuration conf = new Configuration(TEST_UTIL.getConfiguration());
    conf.set(WALFactory.WAL_PROVIDER, "filesystem");
    CommonFSUtils.setRootDir(conf, dir);
    FSTableDescriptors fsTableDescriptors = new FSTableDescriptors(TEST_UTIL.getConfiguration());
    FSTableDescriptors.tryUpdateMetaTableDescriptor(TEST_UTIL.getConfiguration());
    TableDescriptor metaTableDescriptor = fsTableDescriptors.get(TableName.META_TABLE_NAME);
    conf.set(FSHLogProvider.WRITER_IMPL, HighLatencySyncWriter.class.getName());
    final WALFactory wals = new WALFactory(conf, TestLogRollingNoCluster.class.getName());
    final WAL wal = wals.getWAL(null);
    Appender[] appenders = null;
    final int numThreads = NUM_THREADS;
    appenders = new Appender[numThreads];
    try {
        for (int i = 0; i < numThreads; i++) {
            // Have each appending thread write 'count' entries
            appenders[i] = new Appender(metaTableDescriptor, wal, i, NUM_ENTRIES);
        }
        for (int i = 0; i < numThreads; i++) {
            appenders[i].start();
        }
        for (int i = 0; i < numThreads; i++) {
            // ensure that all threads are joined before closing the wal
            appenders[i].join();
        }
    } finally {
        wals.close();
    }
    for (int i = 0; i < numThreads; i++) {
        assertFalse("Error: " + appenders[i].getException(), appenders[i].isException());
    }
    TEST_UTIL.shutdownMiniDFSCluster();
}

