    CountDownLatch latch = new CountDownLatch(numThreads);
    for (int i = 0; i < numThreads; i++) {
        final TableName tableName = TableName.valueOf("tab_" + i);
        long size = i;
        new Thread(() -> {
            for (int j = 0; j < numIters; j++) {
