@Test
public void testSyncFutureCacheLifeCycle() throws Exception {
    final Configuration conf = HBaseConfiguration.create();
    SyncFutureCache cache = new SyncFutureCache(conf);
    try {
        SyncFuture future0 = cache.getIfPresentOrNew().reset(0, false);
        assertNotNull(future0);
        // Get another future from the same thread, should be different one.
        SyncFuture future1 = cache.getIfPresentOrNew().reset(1, false);
        assertNotNull(future1);
        assertNotSame(future0, future1);
        cache.offer(future1);
        // Should override.
        cache.offer(future0);
        SyncFuture future3 = cache.getIfPresentOrNew();
        assertEquals(future3, future0);
        final SyncFuture[] future4 = new SyncFuture[1];
        // From a different thread
        CompletableFuture.runAsync(() -> future4[0] = cache.getIfPresentOrNew().reset(4, false)).get();
        assertNotNull(future4[0]);
        assertNotSame(future3, future4[0]);
        // Clean up
        cache.offer(future3);
        cache.offer(future4[0]);
    } finally {
        cache.clear();
    }
}

/**
 * Add a bunch of dummy data and roll the logs every two insert. We should end up with 10 rolled
 * files (plus the roll called in the constructor). Also test adding a listener while it's
 * running.
 */
@Test
public void testActionListener() throws Exception {
    DummyWALActionsListener observer = new DummyWALActionsListener();
    final WALFactory wals = new WALFactory(conf, "testActionListener");
    wals.getWALProvider().addWALActionsListener(observer);
    DummyWALActionsListener laterobserver = new DummyWALActionsListener();
    RegionInfo hri = RegionInfoBuilder.newBuilder(TableName.valueOf(SOME_BYTES)).setStartKey(SOME_BYTES).setEndKey(SOME_BYTES).build();
    final WAL wal = wals.getWAL(hri);
    MultiVersionConcurrencyControl mvcc = new MultiVersionConcurrencyControl();
    for (int i = 0; i < 20; i++) {
        byte[] b = Bytes.toBytes(i + "");
        KeyValue kv = new KeyValue(b, b, b);
        WALEdit edit = new WALEdit();
        edit.add(kv);
        NavigableMap<byte[], Integer> scopes = new TreeMap<>(Bytes.BYTES_COMPARATOR);
        scopes.put(b, 0);
        long txid = wal.appendData(hri, new WALKeyImpl(hri.getEncodedNameAsBytes(), TableName.valueOf(b), 0, mvcc, scopes), edit);
        wal.sync(txid);
        if (i == 10) {
            wal.registerWALActionsListener(laterobserver);
        }
        if (i % 2 == 0) {
            wal.rollWriter();
        }
    }
    wal.close();
    assertEquals(11, observer.preLogRollCounter);
    assertEquals(11, observer.postLogRollCounter);
    assertEquals(5, laterobserver.preLogRollCounter);
    assertEquals(5, laterobserver.postLogRollCounter);
    assertEquals(1, observer.closedCount);
}

