@Test
public void testValueCompression() throws Exception {
    final byte[] row_1 = Bytes.toBytes("row_1");
    final byte[] value_1 = new byte[20];
    Bytes.zero(value_1);
    final byte[] row_2 = Bytes.toBytes("row_2");
    final byte[] value_2 = new byte[Bytes.SIZEOF_LONG];
    Bytes.random(value_2);
    final byte[] row_3 = Bytes.toBytes("row_3");
    final byte[] value_3 = new byte[100];
    Bytes.random(value_3);
    final byte[] row_4 = Bytes.toBytes("row_4");
    final byte[] value_4 = new byte[128];
    fillBytes(value_4, Bytes.toBytes("DEADBEEF"));
    final byte[] row_5 = Bytes.toBytes("row_5");
    final byte[] value_5 = new byte[64];
    fillBytes(value_5, Bytes.toBytes("CAFEBABE"));
    Configuration conf = new Configuration(false);
    WALCellCodec codec = new WALCellCodec(conf, new CompressionContext(LRUDictionary.class, false, true, true, compression));
    ByteArrayOutputStream bos = new ByteArrayOutputStream();
    Encoder encoder = codec.getEncoder(bos);
    encoder.write(createKV(row_1, value_1, 0));
    encoder.write(createOffheapKV(row_2, value_2, 0));
    encoder.write(createKV(row_3, value_3, 0));
    encoder.write(createOffheapKV(row_4, value_4, 0));
    encoder.write(createKV(row_5, value_5, 0));
    encoder.flush();
    try (InputStream is = new ByteArrayInputStream(bos.toByteArray())) {
        Decoder decoder = codec.getDecoder(is);
        decoder.advance();
        KeyValue kv = (KeyValue) decoder.current();
        assertTrue(Bytes.equals(row_1, 0, row_1.length, kv.getRowArray(), kv.getRowOffset(), kv.getRowLength()));
        assertTrue(Bytes.equals(value_1, 0, value_1.length, kv.getValueArray(), kv.getValueOffset(), kv.getValueLength()));
        decoder.advance();
        kv = (KeyValue) decoder.current();
        assertTrue(Bytes.equals(row_2, 0, row_2.length, kv.getRowArray(), kv.getRowOffset(), kv.getRowLength()));
        assertTrue(Bytes.equals(value_2, 0, value_2.length, kv.getValueArray(), kv.getValueOffset(), kv.getValueLength()));
        decoder.advance();
        kv = (KeyValue) decoder.current();
        assertTrue(Bytes.equals(row_3, 0, row_3.length, kv.getRowArray(), kv.getRowOffset(), kv.getRowLength()));
        assertTrue(Bytes.equals(value_3, 0, value_3.length, kv.getValueArray(), kv.getValueOffset(), kv.getValueLength()));
        decoder.advance();
        kv = (KeyValue) decoder.current();
        assertTrue(Bytes.equals(row_4, 0, row_4.length, kv.getRowArray(), kv.getRowOffset(), kv.getRowLength()));
        assertTrue(Bytes.equals(value_4, 0, value_4.length, kv.getValueArray(), kv.getValueOffset(), kv.getValueLength()));
        decoder.advance();
        kv = (KeyValue) decoder.current();
        assertTrue(Bytes.equals(row_5, 0, row_5.length, kv.getRowArray(), kv.getRowOffset(), kv.getRowLength()));
        assertTrue(Bytes.equals(value_5, 0, value_5.length, kv.getValueArray(), kv.getValueOffset(), kv.getValueLength()));
    }
}

