/**
 * This test is for HBASE-27230. When {@link WAL#sync} timeout, it would throws
 * {@link WALSyncTimeoutIOException},and when {@link HRegion#doWALAppend} catches this exception
 * it aborts the RegionServer.
 */
@Test
public void testWALSyncWriteException() throws Exception {
    final HRegionForTest region = this.createTable();
    String oldThreadName = Thread.currentThread().getName();
    Thread.currentThread().setName(USER_THREAD_NAME);
    try {
        byte[] rowKey1 = Bytes.toBytes(1);
        byte[] value1 = Bytes.toBytes(3);
        Thread.sleep(2000);
        testWALTimout = true;
        /**
         * The {@link WAL#sync} would timeout and throws {@link WALSyncTimeoutIOException},when
         * {@link HRegion#doWALAppend} catches this exception it aborts the RegionServer.
         */
        try {
            region.put(new Put(rowKey1).addColumn(FAMILY, QUAL, value1));
            fail();
        } catch (WALSyncTimeoutIOException e) {
            assertTrue(e != null);
        }
        assertTrue(region.getRSServices().isAborted());
    } finally {
        Thread.currentThread().setName(oldThreadName);
        testWALTimout = false;
    }
}

@Test
public void testWALDurability() throws IOException {
    byte[] bytes = Bytes.toBytes(getName());
    Put put = new Put(bytes);
    put.addColumn(COLUMN_FAMILY_BYTES, Bytes.toBytes("1"), bytes);
    // global hbase.wal.hsync false, no override in put call - hflush
    conf.set(HRegion.WAL_HSYNC_CONF_KEY, "false");
    FileSystem fs = FileSystem.get(conf);
    Path rootDir = new Path(dir + getName());
    T wal = getWAL(fs, rootDir, getName(), conf);
    HRegion region = initHRegion(tableName, null, null, conf, wal);
    try {
        resetSyncFlag(wal);
        assertNull(getSyncFlag(wal));
        assertNull(getWriterSyncFlag(wal));
        region.put(put);
        assertFalse(getSyncFlag(wal));
        assertFalse(getWriterSyncFlag(wal));
        // global hbase.wal.hsync false, durability set in put call - fsync
        put.setDurability(Durability.FSYNC_WAL);
        resetSyncFlag(wal);
        assertNull(getSyncFlag(wal));
        assertNull(getWriterSyncFlag(wal));
        region.put(put);
        assertTrue(getSyncFlag(wal));
        assertTrue(getWriterSyncFlag(wal));
    } finally {
        HBaseTestingUtil.closeRegionAndWAL(region);
    }
    // global hbase.wal.hsync true, no override in put call
    conf.set(HRegion.WAL_HSYNC_CONF_KEY, "true");
    fs = FileSystem.get(conf);
    wal = getWAL(fs, rootDir, getName(), conf);
    region = initHRegion(tableName, null, null, conf, wal);
    try {
        resetSyncFlag(wal);
        assertNull(getSyncFlag(wal));
        assertNull(getWriterSyncFlag(wal));
        region.put(put);
        assertTrue(getSyncFlag(wal));
        assertTrue(getWriterSyncFlag(wal));
        // global hbase.wal.hsync true, durability set in put call - fsync
        put.setDurability(Durability.FSYNC_WAL);
        resetSyncFlag(wal);
        assertNull(getSyncFlag(wal));
        assertNull(getWriterSyncFlag(wal));
        region.put(put);
        assertTrue(getSyncFlag(wal));
        assertTrue(getWriterSyncFlag(wal));
        // global hbase.wal.hsync true, durability set in put call - sync
        put = new Put(bytes);
        put.addColumn(COLUMN_FAMILY_BYTES, Bytes.toBytes("1"), bytes);
        put.setDurability(Durability.SYNC_WAL);
        resetSyncFlag(wal);
        assertNull(getSyncFlag(wal));
        assertNull(getWriterSyncFlag(wal));
        region.put(put);
        assertFalse(getSyncFlag(wal));
        assertFalse(getWriterSyncFlag(wal));
    } finally {
        HBaseTestingUtil.closeRegionAndWAL(region);
    }
}

@Test
public void test() {
    ReplicationLogCleanerBarrier barrier = new ReplicationLogCleanerBarrier();
    assertThrows(IllegalStateException.class, () -> barrier.stop());
    assertThrows(IllegalStateException.class, () -> barrier.enable());
    assertTrue(barrier.start());
    assertThrows(IllegalStateException.class, () -> barrier.start());
    assertThrows(IllegalStateException.class, () -> barrier.enable());
    assertFalse(barrier.disable());
    assertThrows(IllegalStateException.class, () -> barrier.enable());
    barrier.stop();
    for (int i = 0; i < 3; i++) {
        assertTrue(barrier.disable());
        assertFalse(barrier.start());
    }
    for (int i = 0; i < 3; i++) {
        assertFalse(barrier.start());
        barrier.enable();
    }
    assertTrue(barrier.start());
}

