    byte[] endKey = new byte[] { (byte) 0xFF, 0x00, (byte) 0xFF, (byte) 0xFF, 0x01 };
    RegionInfo regionA = RegionInfoBuilder.newBuilder(tableName).setEndKey(endKey).setRegionId(1).build();
