@Test
public void testPermissionList() throws Exception {
    final TableName tableName = TableName.valueOf(name.getMethodName());
    final byte[] family1 = Bytes.toBytes("f1");
    final byte[] family2 = Bytes.toBytes("f2");
    final byte[] qualifier = Bytes.toBytes("q");
    // create table
    Admin admin = TEST_UTIL.getAdmin();
    if (admin.tableExists(tableName)) {
        deleteTable(TEST_UTIL, tableName);
    }
    TableDescriptor tableDescriptor = TableDescriptorBuilder.newBuilder(tableName).setColumnFamily(ColumnFamilyDescriptorBuilder.of(family1)).setColumnFamily(ColumnFamilyDescriptorBuilder.of(family2)).build();
    createTable(TEST_UTIL, USER_OWNER, tableDescriptor);
    try {
        List<UserPermission> perms = admin.getUserPermissions(GetUserPermissionsRequest.newBuilder(tableName).build());
        UserPermission ownerperm = new UserPermission(USER_OWNER.getName(), Permission.newBuilder(tableName).withActions(Action.values()).build());
        assertTrue("Owner should have all permissions on table", hasFoundUserPermission(ownerperm, perms));
        User user = User.createUserForTesting(TEST_UTIL.getConfiguration(), "user", new String[0]);
        String userName = user.getShortName();
        UserPermission up = new UserPermission(userName, Permission.newBuilder(tableName).withFamily(family1).withQualifier(qualifier).withActions(Permission.Action.READ).build());
        assertFalse("User should not be granted permission: " + up.toString(), hasFoundUserPermission(up, perms));
        // grant read permission
        grantOnTable(TEST_UTIL, user.getShortName(), tableName, family1, qualifier, Permission.Action.READ);
        perms = admin.getUserPermissions(GetUserPermissionsRequest.newBuilder(tableName).build());
        UserPermission upToVerify = new UserPermission(userName, Permission.newBuilder(tableName).withFamily(family1).withQualifier(qualifier).withActions(Permission.Action.READ).build());
        assertTrue("User should be granted permission: " + upToVerify.toString(), hasFoundUserPermission(upToVerify, perms));
        upToVerify = new UserPermission(userName, Permission.newBuilder(tableName).withFamily(family1).withQualifier(qualifier).withActions(Permission.Action.WRITE).build());
        assertFalse("User should not be granted permission: " + upToVerify.toString(), hasFoundUserPermission(upToVerify, perms));
        // grant read+write
        grantOnTable(TEST_UTIL, user.getShortName(), tableName, family1, qualifier, Permission.Action.WRITE, Permission.Action.READ);
        perms = admin.getUserPermissions(GetUserPermissionsRequest.newBuilder(tableName).build());
        upToVerify = new UserPermission(userName, Permission.newBuilder(tableName).withFamily(family1).withQualifier(qualifier).withActions(Permission.Action.WRITE, Permission.Action.READ).build());
        assertTrue("User should be granted permission: " + upToVerify.toString(), hasFoundUserPermission(upToVerify, perms));
        // revoke
        revokeFromTable(TEST_UTIL, user.getShortName(), tableName, family1, qualifier, Permission.Action.WRITE, Permission.Action.READ);
        perms = admin.getUserPermissions(GetUserPermissionsRequest.newBuilder(tableName).build());
        assertFalse("User should not be granted permission: " + upToVerify.toString(), hasFoundUserPermission(upToVerify, perms));
        User newOwner = User.createUserForTesting(conf, "new_owner", new String[] {});
        grantOnTable(TEST_UTIL, newOwner.getShortName(), tableName, null, null, Permission.Action.values());
        perms = admin.getUserPermissions(GetUserPermissionsRequest.newBuilder(tableName).build());
        UserPermission newOwnerperm = new UserPermission(newOwner.getName(), Permission.newBuilder(tableName).withActions(Action.values()).build());
        assertTrue("New owner should have all permissions on table", hasFoundUserPermission(newOwnerperm, perms));
    } finally {
        // delete table
        deleteTable(TEST_UTIL, tableName);
    }
}

