@Test
public void testEarlyScanTermination() throws Exception {
    // Grant USER_OTHER access to TEST_FAMILY1 only
    grantOnTable(TEST_UTIL, USER_OTHER.getShortName(), testTable.getTableName(), TEST_FAMILY1, null, Action.READ);
    // Set up test data
    verifyAllowed(new AccessTestAction() {

        @Override
        public Object run() throws Exception {
            // force a new RS connection
            conf.set("testkey", TEST_UTIL.getRandomUUID().toString());
            Connection connection = ConnectionFactory.createConnection(conf);
            Table t = connection.getTable(testTable.getTableName());
            try {
                Put put = new Put(TEST_ROW).addColumn(TEST_FAMILY1, TEST_Q1, ZERO);
                t.put(put);
                // Set a READ cell ACL for USER_OTHER on this value in FAMILY2
                put = new Put(TEST_ROW).addColumn(TEST_FAMILY2, TEST_Q1, ZERO);
                put.setACL(USER_OTHER.getShortName(), new Permission(Action.READ));
                t.put(put);
                // Set an empty cell ACL for USER_OTHER on this other value in FAMILY2
                put = new Put(TEST_ROW).addColumn(TEST_FAMILY2, TEST_Q2, ZERO);
                put.setACL(USER_OTHER.getShortName(), new Permission());
                t.put(put);
            } finally {
                t.close();
                connection.close();
            }
            return null;
        }
    }, USER_OWNER);
    // A scan of FAMILY1 will be allowed
    verifyAllowed(new AccessTestAction() {

        @Override
        public Object run() throws Exception {
            // force a new RS connection
            conf.set("testkey", TEST_UTIL.getRandomUUID().toString());
            Connection connection = ConnectionFactory.createConnection(conf);
            Table t = connection.getTable(testTable.getTableName());
            try {
                Scan scan = new Scan().addFamily(TEST_FAMILY1);
                Result result = t.getScanner(scan).next();
                if (result != null) {
                    assertTrue("Improper exclusion", result.containsColumn(TEST_FAMILY1, TEST_Q1));
                    assertFalse("Improper inclusion", result.containsColumn(TEST_FAMILY2, TEST_Q1));
                    return result.listCells();
                }
                return null;
            } finally {
                t.close();
                connection.close();
            }
        }
    }, USER_OTHER);
    // A scan of FAMILY1 and FAMILY2 will produce results for FAMILY1 without
    // throwing an exception, however no cells from FAMILY2 will be returned
    // because we early out checks at the CF level.
    verifyAllowed(new AccessTestAction() {

        @Override
        public Object run() throws Exception {
            // force a new RS connection
            conf.set("testkey", TEST_UTIL.getRandomUUID().toString());
            Connection connection = ConnectionFactory.createConnection(conf);
            Table t = connection.getTable(testTable.getTableName());
            try {
                Scan scan = new Scan();
                Result result = t.getScanner(scan).next();
                if (result != null) {
                    assertTrue("Improper exclusion", result.containsColumn(TEST_FAMILY1, TEST_Q1));
                    assertFalse("Improper inclusion", result.containsColumn(TEST_FAMILY2, TEST_Q1));
                    return result.listCells();
                }
                return null;
            } finally {
                t.close();
                connection.close();
            }
        }
    }, USER_OTHER);
    // A scan of FAMILY2 will throw an AccessDeniedException
    verifyDenied(new AccessTestAction() {

        @Override
        public Object run() throws Exception {
            // force a new RS connection
            conf.set("testkey", TEST_UTIL.getRandomUUID().toString());
            Connection connection = ConnectionFactory.createConnection(conf);
            Table t = connection.getTable(testTable.getTableName());
            try {
                Scan scan = new Scan().addFamily(TEST_FAMILY2);
                Result result = t.getScanner(scan).next();
                if (result != null) {
                    return result.listCells();
                }
                return null;
            } finally {
                t.close();
                connection.close();
            }
        }
    }, USER_OTHER);
    // Now grant USER_OTHER access to TEST_FAMILY2:TEST_Q2
    grantOnTable(TEST_UTIL, USER_OTHER.getShortName(), testTable.getTableName(), TEST_FAMILY2, TEST_Q2, Action.READ);
    // A scan of FAMILY1 and FAMILY2 will produce combined results. In FAMILY2
    // we have access granted to Q2 at the CF level. Because we early out
    // checks at the CF level the cell ACL on Q1 also granting access is ignored.
    verifyAllowed(new AccessTestAction() {

        @Override
        public Object run() throws Exception {
            // force a new RS connection
            conf.set("testkey", TEST_UTIL.getRandomUUID().toString());
            Connection connection = ConnectionFactory.createConnection(conf);
            Table t = connection.getTable(testTable.getTableName());
            try {
                Scan scan = new Scan();
                Result result = t.getScanner(scan).next();
                if (result != null) {
                    assertTrue("Improper exclusion", result.containsColumn(TEST_FAMILY1, TEST_Q1));
                    assertFalse("Improper inclusion", result.containsColumn(TEST_FAMILY2, TEST_Q1));
                    assertTrue("Improper exclusion", result.containsColumn(TEST_FAMILY2, TEST_Q2));
                    return result.listCells();
                }
                return null;
            } finally {
                t.close();
                connection.close();
            }
        }
    }, USER_OTHER);
}

@Test
public void testGrantGlobal1() throws Exception {
    final String grantUserName = name.getMethodName();
    User grantUser = User.createUserForTesting(conf, grantUserName, new String[] {});
    String namespace = name.getMethodName();
    TableName table = TableName.valueOf(namespace, name.getMethodName());
    String snapshot1 = namespace + "s1";
    String snapshot2 = namespace + "s2";
    TestHDFSAclHelper.createTableAndPut(TEST_UTIL, table);
    snapshotAndWait(snapshot1, table);
    // grant G(R)
    SecureTestUtil.grantGlobal(TEST_UTIL, grantUserName, READ);
    TestHDFSAclHelper.canUserScanSnapshot(TEST_UTIL, grantUser, snapshot1, 6);
    assertTrue(hasUserGlobalHdfsAcl(aclTable, grantUserName));
    // grant G(W) with merging existing permissions
    admin.grant(new UserPermission(grantUserName, Permission.newBuilder().withActions(WRITE).build()), true);
    TestHDFSAclHelper.canUserScanSnapshot(TEST_UTIL, grantUser, snapshot1, 6);
    assertTrue(hasUserGlobalHdfsAcl(aclTable, grantUserName));
    // grant G(W) without merging
    SecureTestUtil.grantGlobal(TEST_UTIL, grantUserName, WRITE);
    TestHDFSAclHelper.canUserScanSnapshot(TEST_UTIL, grantUser, snapshot1, -1);
    assertFalse(hasUserGlobalHdfsAcl(aclTable, grantUserName));
    // grant G(R)
    SecureTestUtil.grantGlobal(TEST_UTIL, grantUserName, READ);
    TestHDFSAclHelper.canUserScanSnapshot(TEST_UTIL, grantUser, snapshot1, 6);
    // take a snapshot and ACLs are inherited automatically
    snapshotAndWait(snapshot2, table);
    TestHDFSAclHelper.canUserScanSnapshot(TEST_UTIL, grantUser, snapshot2, 6);
    assertTrue(hasUserGlobalHdfsAcl(aclTable, grantUserName));
    deleteTable(table);
}

