    }
    // retrieve the same
    ListMultimap<String, UserPermission> perms = PermissionStorage.getTablePermissions(conf, TEST_TABLE);
    List<UserPermission> userPerms = perms.get("george");
    assertNotNull("Should have permissions for george", userPerms);
