    exceptionCaught = false;
    try {
        admin.createNamespace(NamespaceDescriptor.SYSTEM_NAMESPACE);
    } catch (IOException exp) {
        LOG.warn(exp.toString(), exp);
        exceptionCaught = true;
    } finally {
