        desSet = desGet.getFamilyMap().get(entry.getKey());
        for (byte[] qualifier : set) {
            assertTrue(desSet.contains(qualifier));
        }
    }
    assertEquals(get.getMaxVersions(), desGet.getMaxVersions());
